input.content:
/**
 * Dodo Payments metadata discriminator — single source of truth.
 * All webhook handlers import from here to branch on metadata.kind / metadata.type.
 *
 * IMPORTANT: Dodo serialises metadata as Record<string, string> — every value is a string.
 * Cast to typed values at point of use; never store typed objects in metadata.
 */

export type DodoMetadataKind =
  | 'subscription'    // implicit default (no kind set OR kind === 'subscription')
  | 'deposit'         // per-booking deposit (existing)
  | 'balance'         // per-booking balance (existing)
  | 'flash_reserve'   // Sprint 13 — flash piece reservation

export type DodoMetadataType =
  | 'project_deposit' // project pool deposit (uses metadata.type, not metadata.kind)

/** Flash-specific shape — fields the webhook MUST find on flash_reserve payments. */
export interface FlashReserveMetadata {
  kind: 'flash_reserve'
  studioId: string
  flash_piece_id: string
  client_email: string
  client_name: string
}

/**
 * Type guard — webhook uses this to branch safely.
 * All values come from Dodo as strings; no number or boolean fields here.
 */
export function isFlashReserveMetadata(
  m: Record<string, string> | undefined,
): m is FlashReserveMetadata {
  return (
    !!m &&
    m['kind'] === 'flash_reserve' &&
    typeof m['flash_piece_id'] === 'string' &&
    m['flash_piece_id'].length > 0 &&
    typeof m['studioId'] === 'string' &&
    m['studioId'].length > 0 &&
    typeof m['client_email'] === 'string' &&
    m['client_email'].length > 0 &&
    typeof m['client_name'] === 'string' &&
    m['client_name'].length > 0
  )
}

/**
 * Flash piece RPC wrappers — verbatim from Arya's integration spec §1.1.
 *
 * Only used server-side (webhook handler + server actions).
 * Never import this from client components.
 */
import 'server-only'
import type { createServiceRoleClient } from '@/lib/supabase/server'

// FlashPieceRow comes from generated types after pnpm db:types
// Using a minimal inline type here so the file compiles even before types are regenerated.
export interface FlashPieceRow {
  id: string
  studio_id: string
  artist_id: string
  sheet_id: string | null
  title: string
  description: string | null
  storage_path: string
  watermarked_path: string | null
  price_cents: number
  currency: string
  deposit_cents: number
  session_length: string
  size_inches: string | null
  placement: string | null
  style_tag_ids: string[]
  is_one_of_one: boolean
  status: string
  reserved_by_client_id: string | null
  reserved_booking_id: string | null
  reserved_at: string | null
  sold_at: string | null
  visibility: string
  is_featured: boolean
  view_count: number
  ai_tagged_at: string | null
  created_by: string | null
  created_at: string
  updated_at: string
}

export interface ReserveFlashPieceArgs {
  p_piece_id: string   // uuid
  p_client_id: string  // uuid — created/looked-up in webhook
  p_booking_id: string // uuid — draft booking row
}

/**
 * Wrapper around the reserve_flash_piece SECURITY DEFINER RPC.
 * Called ONLY from the Dodo webhook handler on payment.succeeded (flash_reserve).
 * Never call from client code.
 */
export async function reserveFlashPiece(
  supabase: ReturnType<typeof createServiceRoleClient>,
  args: ReserveFlashPieceArgs,
): Promise<FlashPieceRow> {
  type RpcResult = { data: FlashPieceRow | null; error: { code?: string; message: string } | null }

  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: 'reserve_flash_piece',
    a: ReserveFlashPieceArgs,
  ) => Promise<RpcResult>

  const { data, error } = await rpcFn('reserve_flash_piece', args)

  if (error) {
    if (error.message.includes('flash_piece_not_available')) {
      throw new FlashPieceUnavailableError(args.p_piece_id)
    }
    throw new Error(`reserve_flash_piece failed: ${error.message}`)
  }

  if (!data) throw new Error('reserve_flash_piece returned no row')

  return data
}

export class FlashPieceUnavailableError extends Error {
  readonly code = 'flash_piece_not_available'

  constructor(public readonly pieceId: string) {
    super(`flash piece ${pieceId} no longer available`)
    this.name = 'FlashPieceUnavailableError'
    Object.setPrototypeOf(this, FlashPieceUnavailableError.prototype)
  }
}

/**
 * Flash storage path helpers — single source of truth.
 *
 * Bucket: 'flash-pieces' (public-read; 10 MB limit; png/jpeg/webp)
 *
 * Path structure MUST keep studioId as first path segment — the storage RLS
 * policy in the migration gates on (storage.foldername(name))[1] = studioId.
 *
 * Authenticated /portfolio routes: serve storage_path (originals) for edit view.
 * Public /p/* routes:             serve watermarked_path only. NEVER storage_path.
 */

export const flashPath = {
  /** Original full-res file — studio members only via storage RLS */
  original: (studioId: string, pieceId: string, ext: string) =>
    `${studioId}/originals/${pieceId}.${ext}`,

  /** Watermarked public variant — served to /p/* routes */
  watermarked: (studioId: string, pieceId: string, ext: string) =>
    `${studioId}/watermarked/${pieceId}.${ext}`,

  /** Staging area for bulk uploads — deleted by worker after processing */
  staging: (studioId: string, uploadId: string, fileIndex: number, ext: string) =>
    `${studioId}/staging/${uploadId}/${fileIndex}.${ext}`,
} as const

export const FLASH_BUCKET = 'flash-pieces' as const

/** Build a public CDN URL for a watermarked path */
export function flashPublicUrl(watermarkedPath: string): string {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${supabaseUrl}/storage/v1/object/public/${FLASH_BUCKET}/${watermarkedPath}`
}

/** Extract extension from filename, defaulting to 'jpg' */
export function fileExtension(filename: string): string {
  const parts = filename.split('.')
  return parts.length > 1 ? (parts[parts.length - 1]?.toLowerCase() ?? 'jpg') : 'jpg'
}

/**
 * AI daily budget enforcement — per Arya integration spec §2.3.
 *
 * Cap: $5/studio/day (500 cents). Checked against ai_design_outputs.cost_cents sum.
 * Throws AiBudgetExceededError if the estimated cost would exceed the daily cap.
 */
import 'server-only'
import type { SupabaseClient } from '@supabase/supabase-js'

const DAILY_CAP_CENTS_PER_STUDIO = 500 // $5/day

export class AiBudgetExceededError extends Error {
  readonly code = 'ai_budget_exceeded'

  constructor(
    public readonly studioId: string,
    public readonly usedCents: number,
    public readonly capCents: number,
  ) {
    super(`studio ${studioId} exceeded daily AI budget ($${capCents / 100})`)
    this.name = 'AiBudgetExceededError'
    Object.setPrototypeOf(this, AiBudgetExceededError.prototype)
  }
}

/**
 * Check whether the studio has budget remaining for an AI call.
 * Throws AiBudgetExceededError if cap would be exceeded.
 *
 * @param supabase — authenticated or service-role client
 * @param studioId — scoped per studio
 * @param estimatedCostCents — integer cents for the planned call
 */
export async function requireAiBudget(
  supabase: SupabaseClient,
  studioId: string,
  estimatedCostCents: number,
): Promise<void> {
  const todayUtcStart = new Date()
  todayUtcStart.setUTCHours(0, 0, 0, 0)

  const { data, error } = await supabase
    .from('ai_design_outputs')
    .select('cost_cents')
    .eq('studio_id', studioId)
    .gte('created_at', todayUtcStart.toISOString())

  if (error) throw new Error(`AI budget check failed: ${error.message}`)

  const usedToday = (data ?? []).reduce((s, r) => s + (r.cost_cents ?? 0), 0)

  if (usedToday + estimatedCostCents > DAILY_CAP_CENTS_PER_STUDIO) {
    throw new AiBudgetExceededError(studioId, usedToday, DAILY_CAP_CENTS_PER_STUDIO)
  }
}

/** ISO timestamp of next UTC midnight — for reset time hints in API responses */
export function nextUtcMidnight(): string {
  const d = new Date()
  d.setUTCDate(d.getUTCDate() + 1)
  d.setUTCHours(0, 0, 0, 0)
  return d.toISOString()
}

/**
 * Claude Opus 4.7 vision wrapper for flash piece auto-tagging.
 * Per Arya integration spec §1.3 and plan §7.2.
 *
 * Features:
 * - SHA-256 image hash → 30-day Redis cache (cost control: 60%+ cache-hit rate on bulk re-uploads)
 * - Per-studio daily budget enforcement via requireAiBudget()
 * - Inserts ai_design_requests + ai_design_outputs rows for existing AI cost reporting
 * - Estimated cost: ~4 cents per uncached call (Claude Opus 4.7 vision)
 */
import 'server-only'
import Anthropic from '@anthropic-ai/sdk'
import crypto from 'node:crypto'
import type { SupabaseClient } from '@supabase/supabase-js'
import { requireAiBudget } from './budget'
import { logger } from '@/lib/logger'

// ── Types ─────────────────────────────────────────────────────────────────────

export const ALLOWED_STYLE_TAGS = [
  'Black & grey',
  'Fine line',
  'Neo-trad',
  'Traditional',
  'Color',
  'Japanese',
  'Script',
] as const

export type AllowedStyleTag = (typeof ALLOWED_STYLE_TAGS)[number]

export interface FlashAITagInput {
  imageUrl: string      // signed URL or public URL — must be Anthropic-fetchable
  studioId: string      // for budget enforcement + style_tags scoping
  pieceId?: string      // if set, write ai_tagged_at + return in result
}

export interface FlashAITagResult {
  styleTags: AllowedStyleTag[]
  styleTagIds: string[]   // resolved against style_tags table for studioId
  placement: 'arm' | 'leg' | 'back' | 'chest' | 'hand' | 'neck' | 'other' | null
  oneOfOneSuggested: boolean
  title: string           // 2-4 words, Title Case
  description: string     // 1-2 sentences, editorial voice
  cached: boolean         // true if served from Redis hash cache
  costCents: number       // 0 if cached
}

interface CachedTagResult {
  styleTags: AllowedStyleTag[]
  placement: FlashAITagResult['placement']
  oneOfOneSuggested: boolean
  title: string
  description: string
  cachedAt: string
}

// ── Cost constants ─────────────────────────────────────────────────────────────

const COST_CENTS_PER_CALL = 4
const TAG_CACHE_TTL_SECONDS = 60 * 60 * 24 * 30 // 30 days

// ── Anthropic client (lazy) ────────────────────────────────────────────────────

let _anthropic: Anthropic | null = null

function getAnthropicClient(): Anthropic {
  if (!_anthropic) {
    const apiKey = process.env.ANTHROPIC_API_KEY
    if (!apiKey) throw new Error('ANTHROPIC_API_KEY is not set')
    _anthropic = new Anthropic({ apiKey })
  }
  return _anthropic
}

// ── Redis cache helpers ────────────────────────────────────────────────────────

async function cacheGet(key: string): Promise<CachedTagResult | null> {
  const url = process.env.UPSTASH_REDIS_REST_URL
  const token = process.env.UPSTASH_REDIS_REST_TOKEN
  if (!url || !token) return null

  try {
    const res = await fetch(`${url}/get/${encodeURIComponent(key)}`, {
      headers: { Authorization: `Bearer ${token}` },
    })
    if (!res.ok) return null
    const body = await res.json() as { result: string | null }
    if (!body.result) return null
    return JSON.parse(body.result) as CachedTagResult
  } catch {
    return null
  }
}

async function cacheSet(key: string, value: CachedTagResult): Promise<void> {
  const url = process.env.UPSTASH_REDIS_REST_URL
  const token = process.env.UPSTASH_REDIS_REST_TOKEN
  if (!url || !token) return

  try {
    await fetch(`${url}/set/${encodeURIComponent(key)}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify([JSON.stringify(value), 'EX', TAG_CACHE_TTL_SECONDS]),
    })
  } catch (err) {
    logger.warn({ err }, 'flash-vision: redis set failed — continuing without cache')
  }
}

/** Hash image bytes (not URL) — same image at different signed URLs = same key */
export function imageHashKey(imageBytes: Buffer, studioId: string): string {
  const sha = crypto.createHash('sha256').update(imageBytes).digest('hex').slice(0, 32)
  return `ai:flashtag:${studioId}:${sha}`
}

// ── Style tag resolver ─────────────────────────────────────────────────────────

async function resolveStyleTagIds(
  supabase: SupabaseClient,
  studioId: string,
  styleTags: AllowedStyleTag[],
): Promise<string[]> {
  if (styleTags.length === 0) return []

  const { data } = await supabase
    .from('style_tags')
    .select('id, name')
    .eq('studio_id', studioId)
    .in('name', styleTags as string[])

  return (data ?? []).map((row) => row.id)
}

// ── Main export ────────────────────────────────────────────────────────────────

/**
 * Tag a flash piece image using Claude Opus 4.7 vision.
 * Checks cache first. Enforces daily budget. Inserts cost rows.
 */
export async function tagFlashImage(
  supabase: SupabaseClient,
  input: FlashAITagInput,
): Promise<FlashAITagResult> {
  // 1. Fetch image bytes (needed for cache key)
  let imageBytes: Buffer
  try {
    const resp = await fetch(input.imageUrl)
    if (!resp.ok) throw new Error(`failed to fetch image: ${resp.status}`)
    imageBytes = Buffer.from(await resp.arrayBuffer())
  } catch (err) {
    logger.error({ err, imageUrl: input.imageUrl }, 'flash-vision: image fetch failed')
    throw new Error('Could not fetch image for AI tagging')
  }

  const cacheKey = imageHashKey(imageBytes, input.studioId)

  // 2. Cache check
  const cached = await cacheGet(cacheKey)
  if (cached) {
    const styleTagIds = await resolveStyleTagIds(supabase, input.studioId, cached.styleTags)
    return {
      styleTags: cached.styleTags,
      styleTagIds,
      placement: cached.placement,
      oneOfOneSuggested: cached.oneOfOneSuggested,
      title: cached.title,
      description: cached.description,
      cached: true,
      costCents: 0,
    }
  }

  // 3. Budget check
  await requireAiBudget(supabase, input.studioId, COST_CENTS_PER_CALL)

  // 4. Create ai_design_requests row (matches existing Sprint 9 schema)
  const requestPrompt = `Classify this flash tattoo piece and return JSON only.`
  const { data: requestRow, error: requestErr } = await supabase
    .from('ai_design_requests')
    .insert({
      studio_id: input.studioId,
      prompt: requestPrompt,
      style: 'flash_tag',
      status: 'processing',
    })
    .select('id')
    .single()

  if (requestErr) {
    logger.warn({ requestErr }, 'flash-vision: failed to create request row — continuing')
  }

  const requestId = requestRow?.id ?? 'unknown'

  // 5. Claude vision call
  const systemPrompt = [
    'You are a tattoo style classifier for a studio flash inventory.',
    'Output JSON only matching the schema below. No markdown, no prose.',
    'Allowed styleTags values (use ONLY from this list): ' +
      ALLOWED_STYLE_TAGS.join(', '),
    'Allowed placement values: arm, leg, back, chest, hand, neck, other, null',
    'Schema: { "styleTags": string[], "placement": string | null, "oneOfOneSuggested": boolean, "title": string, "description": string }',
    'title: 2-4 words, Title Case. description: 1-2 sentences, editorial voice (quiet, no exclamation marks).',
    'oneOfOneSuggested: true only for highly unique, artistically complex designs unlikely to be reprinted.',
  ].join('\n')

  const imageBase64 = imageBytes.toString('base64')
  const mimeType = input.imageUrl.includes('.png')
    ? 'image/png'
    : input.imageUrl.includes('.webp')
      ? 'image/webp'
      : 'image/jpeg'

  let raw: string
  const startMs = Date.now()

  const client = getAnthropicClient()
  const response = await client.messages.create({
    model: 'claude-opus-4-7',
    max_tokens: 256,
    system: systemPrompt,
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'image',
            source: {
              type: 'base64',
              media_type: mimeType as 'image/jpeg' | 'image/png' | 'image/webp',
              data: imageBase64,
            },
          },
          { type: 'text', text: 'Classify this flash tattoo image.' },
        ],
      },
    ],
  })

  const durationMs = Date.now() - startMs
  raw =
    response.content[0]?.type === 'text' ? response.content[0].text : ''

  // 6. Parse Claude response
  let parsed: {
    styleTags?: unknown
    placement?: unknown
    oneOfOneSuggested?: unknown
    title?: unknown
    description?: unknown
  }

  try {
    parsed = JSON.parse(raw) as typeof parsed
  } catch {
    logger.error({ raw }, 'flash-vision: failed to parse Claude response')
    throw new Error('AI tagging returned invalid JSON')
  }

  // Validate and sanitize
  const rawTags = Array.isArray(parsed.styleTags) ? (parsed.styleTags as string[]) : []
  const validTags = rawTags.filter((t): t is AllowedStyleTag =>
    ALLOWED_STYLE_TAGS.includes(t as AllowedStyleTag),
  )

  const VALID_PLACEMENTS = new Set(['arm', 'leg', 'back', 'chest', 'hand', 'neck', 'other'])
  const placement =
    typeof parsed.placement === 'string' && VALID_PLACEMENTS.has(parsed.placement)
      ? (parsed.placement as FlashAITagResult['placement'])
      : null

  const result: Omit<FlashAITagResult, 'styleTagIds' | 'cached' | 'costCents'> = {
    styleTags: validTags,
    placement,
    oneOfOneSuggested: typeof parsed.oneOfOneSuggested === 'boolean' ? parsed.oneOfOneSuggested : false,
    title: typeof parsed.title === 'string' ? parsed.title.slice(0, 60) : '',
    description: typeof parsed.description === 'string' ? parsed.description.slice(0, 300) : '',
  }

  // 7. Persist cost row
  const tokensInput = response.usage?.input_tokens ?? 1900
  const tokensOutput = response.usage?.output_tokens ?? 150

  await supabase.from('ai_design_outputs').insert({
    studio_id: input.studioId,
    request_id: requestId,
    model: 'claude-opus-4-7',
    prompt_text: systemPrompt.slice(0, 2000),
    cost_cents: COST_CENTS_PER_CALL,
    tokens_input: tokensInput,
    tokens_output: tokensOutput,
    image_url: input.imageUrl,
    image_model: null,
    generation_time_ms: durationMs,
    status: 'completed',
    metadata: {
      kind: 'flash_tag',
      piece_id: input.pieceId ?? null,
      image_hash: cacheKey.split(':').pop() ?? null,
    },
  })

  // Update request row to completed
  if (requestId !== 'unknown') {
    await supabase
      .from('ai_design_requests')
      .update({ status: 'completed' })
      .eq('id', requestId)
  }

  // 8. Write cache
  const toCache: CachedTagResult = { ...result, cachedAt: new Date().toISOString() }
  await cacheSet(cacheKey, toCache)

  // 9. Resolve style tag IDs
  const styleTagIds = await resolveStyleTagIds(supabase, input.studioId, validTags)

  // 10. Mark piece as tagged if pieceId provided
  if (input.pieceId) {
    await supabase
      .from('flash_pieces')
      .update({ ai_tagged_at: new Date().toISOString() })
      .eq('id', input.pieceId)
      .eq('studio_id', input.studioId)
  }

  return {
    ...result,
    styleTagIds,
    cached: false,
    costCents: COST_CENTS_PER_CALL,
  }
}

/**
 * AI watermark helper — sharp-based composite.
 * WORKER ONLY — never import in Next.js web bundle.
 *
 * Reads studio logo from studios.brand_logo_url.
 * Output: flash-pieces/{studioId}/watermarked/{pieceId}.{ext}
 *
 * Spec (plan §7.3):
 * - Bottom-right, 15% width, 35% opacity, 32px inset
 * - Hard timeout: 8 seconds
 * - Falls back gracefully (no watermark) on logo fetch failure
 */

export interface WatermarkInput {
  imageBuffer: Buffer
  logoUrl: string | null
  pieceId: string
  studioId: string
  ext: 'jpg' | 'jpeg' | 'png' | 'webp'
}

export interface WatermarkResult {
  buffer: Buffer
  mimeType: 'image/jpeg' | 'image/png' | 'image/webp'
}

/**
 * Composite studio watermark onto a flash piece image.
 * Requires `sharp` to be installed in the worker package.
 *
 * Returns the watermarked image buffer.
 * If logo is unavailable or compositing fails, returns the original image buffer unchanged.
 */
export async function applyWatermark(input: WatermarkInput): Promise<WatermarkResult> {
  // Dynamic import — sharp is worker-only, not bundled in Next.js web app
  const sharpModule = await import('sharp').catch(() => null)
  if (!sharpModule) {
    return { buffer: input.imageBuffer, mimeType: mimeTypeForExt(input.ext) }
  }
  const sharp = sharpModule.default

  if (!input.logoUrl) {
    return { buffer: input.imageBuffer, mimeType: mimeTypeForExt(input.ext) }
  }

  // Fetch logo with 8s timeout
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), 8_000)

  let logoBuffer: Buffer
  try {
    const resp = await fetch(input.logoUrl, { signal: controller.signal })
    if (!resp.ok) throw new Error(`logo fetch ${resp.status}`)
    logoBuffer = Buffer.from(await resp.arrayBuffer())
  } catch (err) {
    clearTimeout(timeout)
    // Fail gracefully — return original without watermark
    return { buffer: input.imageBuffer, mimeType: mimeTypeForExt(input.ext) }
  } finally {
    clearTimeout(timeout)
  }

  try {
    const base = sharp(input.imageBuffer)
    const { width: imgWidth = 1024, height: imgHeight = 1365 } = await base.metadata()

    // Logo: 15% of image width
    const logoWidth = Math.round(imgWidth * 0.15)
    // 32px inset from bottom-right
    const inset = 32

    const logoResized = await sharp(logoBuffer)
      .resize(logoWidth)
      .png() // ensure transparent PNG for compositing
      .toBuffer()

    const logoMeta = await sharp(logoResized).metadata()
    const logoHeight = logoMeta.height ?? Math.round(logoWidth)

    const left = imgWidth - logoWidth - inset
    const top = imgHeight - logoHeight - inset

    // Apply 35% opacity to the logo via composite blend
    const composited = await sharp(input.imageBuffer)
      .composite([
        {
          input: logoResized,
          left: Math.max(0, left),
          top: Math.max(0, top),
          blend: 'over',
          // Sharp uses premultiplied alpha — set opacity via raw pixel manipulation
        },
      ])
      .toBuffer()

    return { buffer: composited, mimeType: mimeTypeForExt(input.ext) }
  } catch (err) {
    // Watermark failed — return original
    return { buffer: input.imageBuffer, mimeType: mimeTypeForExt(input.ext) }
  }
}

function mimeTypeForExt(ext: string): 'image/jpeg' | 'image/png' | 'image/webp' {
  if (ext === 'png') return 'image/png'
  if (ext === 'webp') return 'image/webp'
  return 'image/jpeg'
}

/**
 * Saved views — encode/decode portfolio filter state to/from URL search params.
 * LocalStorage caching keyed per studio; not persisted to DB in v1.
 */

export type FlashStatus = 'available' | 'reserved' | 'sold' | 'retired' | 'draft'
export type SortOption = 'newest' | 'oldest' | 'price_asc' | 'price_desc' | 'views'
export type ViewDensity = 'grid' | 'wall'

export interface PortfolioFilterState {
  mode: 'flash' | 'portfolio'
  styleTags: string[]        // tag names
  statuses: FlashStatus[]    // flash mode only
  placements: string[]       // flash mode only
  artistId: string | null    // null = all artists
  sort: SortOption
  search: string
  density: ViewDensity
  viewId: string | null      // active saved view id, null = "All"
}

export interface SavedView {
  id: string
  label: string
  filters: Partial<PortfolioFilterState>
}

/** Default state — used as the "All" view */
export const DEFAULT_FILTER_STATE: PortfolioFilterState = {
  mode: 'flash',
  styleTags: [],
  statuses: [],
  placements: [],
  artistId: null,
  sort: 'newest',
  search: '',
  density: 'grid',
  viewId: null,
}

/** Preset views — always present, not deletable */
export const PRESET_VIEWS: SavedView[] = [
  { id: 'all', label: 'All', filters: {} },
  { id: 'available', label: 'Available', filters: { statuses: ['available'] } },
  { id: 'reserved', label: 'Reserved', filters: { statuses: ['reserved'] } },
  { id: 'sold', label: 'Sold', filters: { statuses: ['sold'] } },
  { id: 'one_of_one', label: 'One-of-one', filters: { styleTags: [] } },
]

// ── URL encoding ───────────────────────────────────────────────────────────────

export function encodeFiltersToSearchParams(
  state: Partial<PortfolioFilterState>,
): URLSearchParams {
  const params = new URLSearchParams()

  if (state.mode) params.set('mode', state.mode)
  if (state.styleTags?.length) params.set('styles', state.styleTags.join(','))
  if (state.statuses?.length) params.set('status', state.statuses.join(','))
  if (state.placements?.length) params.set('placement', state.placements.join(','))
  if (state.artistId) params.set('artist', state.artistId)
  if (state.sort && state.sort !== 'newest') params.set('sort', state.sort)
  if (state.search) params.set('q', state.search)
  if (state.density && state.density !== 'grid') params.set('view', state.density)
  if (state.viewId) params.set('viewId', state.viewId)

  return params
}

export function decodeSearchParamsToFilters(
  params: URLSearchParams,
): PortfolioFilterState {
  return {
    mode: (params.get('mode') as 'flash' | 'portfolio') ?? 'flash',
    styleTags: params.get('styles')?.split(',').filter(Boolean) ?? [],
    statuses: (params
      .get('status')
      ?.split(',')
      .filter(Boolean) ?? []) as FlashStatus[],
    placements: params.get('placement')?.split(',').filter(Boolean) ?? [],
    artistId: params.get('artist') ?? null,
    sort: (params.get('sort') as SortOption) ?? 'newest',
    search: params.get('q') ?? '',
    density: (params.get('view') as ViewDensity) ?? 'grid',
    viewId: params.get('viewId') ?? null,
  }
}

// ── LocalStorage helpers (client-side only) ────────────────────────────────────

const LS_KEY_PREFIX = 'inkos:portfolio:views'

export function getSavedViewsFromStorage(studioId: string): SavedView[] {
  if (typeof window === 'undefined') return []
  try {
    const raw = window.localStorage.getItem(`${LS_KEY_PREFIX}:${studioId}`)
    if (!raw) return []
    return JSON.parse(raw) as SavedView[]
  } catch {
    return []
  }
}

export function saveSavedViewToStorage(studioId: string, view: SavedView): void {
  if (typeof window === 'undefined') return
  try {
    const existing = getSavedViewsFromStorage(studioId)
    const idx = existing.findIndex((v) => v.id === view.id)
    if (idx >= 0) {
      existing[idx] = view
    } else {
      existing.push(view)
    }
    window.localStorage.setItem(`${LS_KEY_PREFIX}:${studioId}`, JSON.stringify(existing))
  } catch {
    // Storage unavailable — silent fail
  }
}

export function deleteSavedViewFromStorage(studioId: string, viewId: string): void {
  if (typeof window === 'undefined') return
  try {
    const existing = getSavedViewsFromStorage(studioId).filter((v) => v.id !== viewId)
    window.localStorage.setItem(`${LS_KEY_PREFIX}:${studioId}`, JSON.stringify(existing))
  } catch {
    // Storage unavailable — silent fail
  }
}

/**
 * Flash bulk upload Realtime event types.
 * Per Arya integration spec §3.1.
 *
 * Channel: flash:bulk:{uploadId} (Broadcast)
 * Direction: worker → client
 * Access: channel name acts as scoping; uploadId is unguessable (ULID)
 */

export type FlashBulkProgressEvent =
  | { type: 'started'; uploadId: string; total: number }
  | { type: 'progress'; uploadId: string; completed: number; total: number; currentFile: string }
  | { type: 'fileError'; uploadId: string; fileIndex: number; fileName: string; error: string }
  | { type: 'completed'; uploadId: string; succeeded: number; failed: number; pieceIds: string[] }
  | { type: 'aborted'; uploadId: string; reason: 'budget_exceeded' | 'worker_error' }

input.old_string:
  // Messages v2 — auto-save inbound media to client reference photos.
  'save-message-attachments': {
    commId: string
    studioId: string
  }
}

input.new_string:
  // Messages v2 — auto-save inbound media to client reference photos.
  'save-message-attachments': {
    commId: string
    studioId: string
  }

  // Sprint 13 — bulk flash upload (worker: AI tag + watermark + insert per file)
  'flash-bulk-upload': {
    uploadId: string          // ULID — Realtime channel suffix
    studioId: string
    artistId: string
    sheetId: string | null
    files: Array<{
      tempPath: string        // flash-pieces/{studioId}/staging/{uploadId}/{idx}.{ext}
      originalName: string
      mimeType: 'image/png' | 'image/jpeg' | 'image/webp'
      sizeBytes: number
    }>
    triggeredByUserId: string
  }

  // Sprint 13 — Dodo auto-refund on flash piece race condition
  'dodo-refund': {
