  }

  // Sprint 13 — ISR path revalidation (worker calls revalidatePath via Next.js API)
  'revalidate-path': {
    paths: string[]
  }
}

input.content:
'use server'

/**
 * Flash piece server actions.
 * All mutations go through these actions — never direct .insert() from client.
 *
 * Auth: all actions require authenticated studio member.
 * AI features: gated by ai_design feature via requireFeatureRpc().
 */
import { redirect } from 'next/navigation'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { requireFeatureRpc } from '@/lib/billing/feature-gate'
import { enqueueJob } from '@/lib/queue'
import { flashPath, fileExtension, FLASH_BUCKET } from '@/lib/storage/flash-paths'
import { tagFlashImage } from '@/lib/ai/flash-vision'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

// ── Schemas ───────────────────────────────────────────────────────────────────

const CreateFlashPieceSchema = z.object({
  artistId: z.string().uuid(),
  title: z.string().min(1).max(120),
  description: z.string().max(500).optional().nullable(),
  priceCents: z.coerce.number().int().min(0),
  depositCents: z.coerce.number().int().min(0).default(0),
  currency: z.string().length(3).default('USD'),
  sessionLength: z.enum(['1h', '2-3h', 'half-day', 'full-day']),
  sizeInches: z.string().max(20).optional().nullable(),
  placement: z.enum(['arm', 'leg', 'back', 'chest', 'hand', 'neck', 'other']).optional().nullable(),
  styleTagIds: z.array(z.string().uuid()).default([]),
  isOneOfOne: z.coerce.boolean().default(false),
  sheetId: z.string().uuid().optional().nullable(),
  visibility: z.enum(['public', 'private']).default('public'),
  isFeatured: z.coerce.boolean().default(false),
  enableWatermark: z.coerce.boolean().default(true),
  aiAutoTag: z.coerce.boolean().default(false),
})

const UpdateFlashPieceSchema = z.object({
  title: z.string().min(1).max(120).optional(),
  description: z.string().max(500).optional().nullable(),
  priceCents: z.coerce.number().int().min(0).optional(),
  depositCents: z.coerce.number().int().min(0).optional(),
  sessionLength: z.enum(['1h', '2-3h', 'half-day', 'full-day']).optional(),
  sizeInches: z.string().max(20).optional().nullable(),
  placement: z.enum(['arm', 'leg', 'back', 'chest', 'hand', 'neck', 'other']).optional().nullable(),
  styleTagIds: z.array(z.string().uuid()).optional(),
  isOneOfOne: z.coerce.boolean().optional(),
  sheetId: z.string().uuid().optional().nullable(),
  visibility: z.enum(['public', 'private']).optional(),
  isFeatured: z.coerce.boolean().optional(),
})

const CreateFlashSheetSchema = z.object({
  title: z.string().min(1).max(120),
  description: z.string().max(500).optional().nullable(),
  dropDate: z.string().date().optional().nullable(),
  coverImageUrl: z.string().url().optional().nullable(),
})

// ── createFlashPiece ──────────────────────────────────────────────────────────

export async function createFlashPiece(formData: FormData): Promise<{ success: true; pieceId: string } | { success: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Parse fields
  const parsed = CreateFlashPieceSchema.safeParse({
    artistId: formData.get('artistId'),
    title: formData.get('title'),
    description: formData.get('description'),
    priceCents: formData.get('priceCents'),
    depositCents: formData.get('depositCents'),
    currency: formData.get('currency') ?? 'USD',
    sessionLength: formData.get('sessionLength'),
    sizeInches: formData.get('sizeInches'),
    placement: formData.get('placement'),
    styleTagIds: formData.getAll('styleTagIds'),
    isOneOfOne: formData.get('isOneOfOne'),
    sheetId: formData.get('sheetId'),
    visibility: formData.get('visibility') ?? 'public',
    isFeatured: formData.get('isFeatured'),
    enableWatermark: formData.get('enableWatermark') ?? 'true',
    aiAutoTag: formData.get('aiAutoTag') ?? 'false',
  })

  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Invalid input' }
  }

  const data = parsed.data
  const imageFile = formData.get('image') as File | null

  if (!imageFile || imageFile.size === 0) {
    return { success: false, error: 'Image is required' }
  }

  // Generate piece ID upfront (used in storage path)
  const pieceId = crypto.randomUUID()
  const ext = fileExtension(imageFile.name)
  const storagePath = flashPath.original(auth.studioId, pieceId, ext)

  // Upload original to flash-pieces bucket
  const imageBytes = new Uint8Array(await imageFile.arrayBuffer())
  const { error: uploadError } = await supabase.storage
    .from(FLASH_BUCKET)
    .upload(storagePath, imageBytes, {
      contentType: imageFile.type,
      upsert: false,
    })

  if (uploadError) {
    logger.error({ uploadError, studioId: auth.studioId, pieceId }, 'createFlashPiece: upload failed')
    return { success: false, error: 'Failed to upload image' }
  }

  // AI auto-tag (Pro+ gated, optional)
  let finalStyleTagIds = data.styleTagIds
  let aiTaggedAt: string | null = null

  if (data.aiAutoTag) {
    try {
      await requireFeatureRpc(supabase, auth.studioId, 'ai_design')
      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
      const imageUrl = `${supabaseUrl}/storage/v1/object/public/${FLASH_BUCKET}/${storagePath}`
      const tagResult = await tagFlashImage(supabase, {
        imageUrl,
        studioId: auth.studioId,
        pieceId,
      })
      if (tagResult.styleTagIds.length > 0) {
        finalStyleTagIds = tagResult.styleTagIds
      }
      aiTaggedAt = new Date().toISOString()
    } catch (err) {
      logger.warn({ err }, 'createFlashPiece: AI tag failed — continuing without tags')
    }
  }

  // Insert flash_pieces row
  const { error: insertError } = await supabase.from('flash_pieces').insert({
    id: pieceId,
    studio_id: auth.studioId,
    artist_id: data.artistId,
    sheet_id: data.sheetId ?? null,
    title: data.title,
    description: data.description ?? null,
    storage_path: storagePath,
    watermarked_path: null, // watermark applied async by worker
    price_cents: data.priceCents,
    currency: data.currency,
    deposit_cents: data.depositCents,
    session_length: data.sessionLength,
    size_inches: data.sizeInches ?? null,
    placement: data.placement ?? null,
    style_tag_ids: finalStyleTagIds,
    is_one_of_one: data.isOneOfOne,
    status: 'available',
    visibility: data.visibility,
    is_featured: data.isFeatured,
    ai_tagged_at: aiTaggedAt,
    created_by: auth.user.authId,
  })

  if (insertError) {
    logger.error({ insertError, studioId: auth.studioId, pieceId }, 'createFlashPiece: insert failed')
    // Clean up storage
    await supabase.storage.from(FLASH_BUCKET).remove([storagePath])
    return { success: false, error: 'Failed to save piece' }
  }

  await logAuditAction(auth.user.authId, 'flash_piece.created', { type: 'flash_pieces', id: pieceId }, { title: data.title }, auth.studioId)

  return { success: true, pieceId }
}

// ── bulkCreateFlashPieces ─────────────────────────────────────────────────────

export async function bulkCreateFlashPieces(
  formData: FormData,
): Promise<{ success: true; uploadId: string } | { success: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // AI gate — bulk upload requires ai_design
  try {
    await requireFeatureRpc(supabase, auth.studioId, 'ai_design')
  } catch {
    return { success: false, error: 'Bulk AI upload requires Pro plan or higher' }
  }

  const artistId = formData.get('artistId')
  const sheetId = formData.get('sheetId')
  const files = formData.getAll('files') as File[]

  if (!artistId || typeof artistId !== 'string') {
    return { success: false, error: 'Artist is required' }
  }
  if (files.length === 0) {
    return { success: false, error: 'No files provided' }
  }
  if (files.length > 50) {
    return { success: false, error: 'Maximum 50 files per bulk upload' }
  }

  const uploadId = generateUploadId()
  const jobFiles: { tempPath: string; originalName: string; mimeType: 'image/png' | 'image/jpeg' | 'image/webp'; sizeBytes: number }[] = []

  // Upload files to staging
  for (let i = 0; i < files.length; i++) {
    const file = files[i]
    if (!file) continue
    const ext = fileExtension(file.name)
    const stagingPath = flashPath.staging(auth.studioId, uploadId, i, ext)

    const bytes = new Uint8Array(await file.arrayBuffer())
    const { error } = await supabase.storage
      .from(FLASH_BUCKET)
      .upload(stagingPath, bytes, { contentType: file.type })

    if (error) {
      logger.warn({ error, file: file.name }, 'bulkCreateFlashPieces: staging upload failed')
      continue
    }

    const mimeType = (file.type === 'image/png' || file.type === 'image/webp')
      ? file.type as 'image/png' | 'image/webp'
      : 'image/jpeg'

    jobFiles.push({
      tempPath: stagingPath,
      originalName: file.name,
      mimeType,
      sizeBytes: file.size,
    })
  }

  if (jobFiles.length === 0) {
    return { success: false, error: 'All file uploads failed' }
  }

  // Enqueue BullMQ job
  await enqueueJob('flash-bulk-upload', {
    uploadId,
    studioId: auth.studioId,
    artistId,
    sheetId: sheetId && typeof sheetId === 'string' ? sheetId : null,
    files: jobFiles,
    triggeredByUserId: auth.user.authId,
  })

  return { success: true, uploadId }
}

