  const parsed = UpdateFlashPieceSchema.safeParse(patch)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Invalid input' }
  }

  const d = parsed.data
  const update: Record<string, unknown> = {}
  if (d.title !== undefined) update.title = d.title
  if (d.description !== undefined) update.description = d.description
  if (d.priceCents !== undefined) update.price_cents = d.priceCents
  if (d.depositCents !== undefined) update.deposit_cents = d.depositCents
  if (d.sessionLength !== undefined) update.session_length = d.sessionLength
  if (d.sizeInches !== undefined) update.size_inches = d.sizeInches
  if (d.placement !== undefined) update.placement = d.placement
  if (d.styleTagIds !== undefined) update.style_tag_ids = d.styleTagIds
  if (d.isOneOfOne !== undefined) update.is_one_of_one = d.isOneOfOne
  if (d.sheetId !== undefined) update.sheet_id = d.sheetId
  if (d.visibility !== undefined) update.visibility = d.visibility
  if (d.isFeatured !== undefined) update.is_featured = d.isFeatured

  const supabase = await createClient()
  const { error } = await supabase
    .from('flash_pieces')
    .update(update)
    .eq('id', id)
