const CreatePortfolioItemSchema = z.object({
  artistId: z.string().uuid(),
  caption: z.string().max(500).optional().nullable(),
  styleTagIds: z.array(z.string().uuid()).default([]),
  isFeatured: z.coerce.boolean().default(false),
  linkedProjectId: z.string().uuid().optional().nullable(),
  date: z.string().date().optional().nullable(),
})

// ── PullFromSession result ─────────────────────────────────────────────────────

export interface PullFromSessionResult {
  itemId: string
  photosCopied: number
  styleTagIds: string[]
  artistId: string
  clientId: string | null
  linkedProjectId: string
}

// ── createPortfolioItem ───────────────────────────────────────────────────────

export async function createPortfolioItem(
  formData: FormData,
): Promise<{ success: true; itemId: string } | { success: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const parsed = CreatePortfolioItemSchema.safeParse({
    artistId: formData.get('artistId'),
    caption: formData.get('caption'),
    styleTagIds: formData.getAll('styleTagIds'),
    isFeatured: formData.get('isFeatured'),
    linkedProjectId: formData.get('linkedProjectId'),
    date: formData.get('date'),
  })

  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Invalid input' }
  }

  const d = parsed.data
  const supabase = await createClient()

  // At least one photo required
  const freshFile = formData.get('freshPhoto') as File | null
  const healedFile = formData.get('healedPhoto') as File | null

  if ((!freshFile || freshFile.size === 0) && (!healedFile || healedFile.size === 0)) {
    return { success: false, error: 'At least one photo (Fresh or Healed) is required' }
  }

  const PORTFOLIO_BUCKET = 'artist-portfolio'
  const itemId = crypto.randomUUID()
  const storagePaths: Record<string, string> = {}

  // Upload progression photos
  const photoSlots: Array<{ key: string; field: string }> = [
    { key: 'reference_path', field: 'referencePhoto' },
    { key: 'stencil_path', field: 'stencilPhoto' },
    { key: 'fresh_path', field: 'freshPhoto' },
    { key: 'healed_path', field: 'healedPhoto' },
  ]

  for (const slot of photoSlots) {
    const file = formData.get(slot.field) as File | null
    if (!file || file.size === 0) continue

    const ext = file.name.split('.').pop()?.toLowerCase() ?? 'jpg'
    const path = `${auth.studioId}/${d.artistId}/${itemId}-${slot.field}.${ext}`

    const bytes = new Uint8Array(await file.arrayBuffer())
    const { error } = await supabase.storage
      .from(PORTFOLIO_BUCKET)
      .upload(path, bytes, { contentType: file.type })

    if (error) {
      logger.warn({ error, slot: slot.key }, 'createPortfolioItem: photo upload failed')
    } else {
      storagePaths[slot.key] = path
    }
  }

  // storage_path = fresh or healed (prefer fresh as primary)
  const primaryPath = storagePaths['fresh_path'] ?? storagePaths['healed_path'] ?? storagePaths['reference_path'] ?? ''

  if (!primaryPath) {
    return { success: false, error: 'Photo upload failed' }
  }

  const { error: insertError } = await supabase
    .from('artist_portfolio_items')
    .insert({
      id: itemId,
      studio_id: auth.studioId,
      artist_id: d.artistId,
      storage_path: primaryPath,
      reference_path: storagePaths['reference_path'] ?? null,
      stencil_path: storagePaths['stencil_path'] ?? null,
      fresh_path: storagePaths['fresh_path'] ?? null,
      healed_path: storagePaths['healed_path'] ?? null,
      healed_at: storagePaths['healed_path'] ? (d.date ?? null) : null,
      caption: d.caption ?? null,
      style_tag_ids: d.styleTagIds,
      is_featured: d.isFeatured,
      linked_project_id: d.linkedProjectId ?? null,
    })

  if (insertError) {
    logger.error({ insertError, studioId: auth.studioId }, 'createPortfolioItem: insert failed')
    return { success: false, error: 'Failed to save portfolio item' }
  }

  await logAuditAction(auth.user.authId, 'portfolio_item.created', { type: 'artist_portfolio_items', id: itemId }, null, auth.studioId)

  return { success: true, itemId }
}

// ── pullFromSession ────────────────────────────────────────────────────────────

export async function pullFromSession(projectId: string): Promise<PullFromSessionResult | { error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Idempotency: if item with linked_project_id = projectId already exists, return it
  const { data: existing } = await supabase
    .from('artist_portfolio_items')
    .select('id, artist_id, style_tag_ids')
    .eq('linked_project_id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (existing) {
    return {
      itemId: existing.id,
      photosCopied: 0,
      styleTagIds: (existing.style_tag_ids as string[]) ?? [],
      artistId: existing.artist_id,
      clientId: null,
      linkedProjectId: projectId,
    }
  }

  // Fetch project data
  const { data: project, error: projectErr } = await supabase
    .from('projects')
    .select('id, title, artist_id, client_id, style_tag_ids, studio_id')
    .eq('id', projectId)
    .maybeSingle()

  if (projectErr || !project) {
    return { error: 'Project not found' }
  }

  if (project.studio_id !== auth.studioId) {
    return { error: 'Not authorized' }
  }

  // Fetch project photos
  const { data: photos } = await supabase
    .from('project_photos')
    .select('id, storage_path, kind, taken_at')
    .eq('project_id', projectId)
    .order('taken_at', { ascending: true })

  const photoList = photos ?? []

  // Map photo kinds to progression stages
  // stencil = pre-session, fresh = end-of-session, healed = 30d post-session
  const kindMap: Record<string, string> = {
    stencil: 'stencil_path',
    fresh: 'fresh_path',
    healed: 'healed_path',
    reference: 'reference_path',
  }

  const PORTFOLIO_BUCKET = 'artist-portfolio'
  const itemId = crypto.randomUUID()
  const stagePaths: Record<string, string> = {}

  for (const photo of photoList) {
    const stage = kindMap[photo.kind ?? '']
    if (!stage || stagePaths[stage]) continue // keep first of each kind

    const srcPath = photo.storage_path
    const ext = srcPath.split('.').pop()?.toLowerCase() ?? 'jpg'
    const destPath = `${auth.studioId}/${project.artist_id}/${itemId}-${stage}.${ext}`

    // Copy: download then re-upload
    const { data: fileData } = await supabase.storage
      .from('booking-photos')
      .download(srcPath)
      .catch(() => ({ data: null }))

    if (!fileData) continue

    const { error: uploadErr } = await supabase.storage
      .from(PORTFOLIO_BUCKET)
      .upload(destPath, fileData)

    if (!uploadErr) {
      stagePaths[stage] = destPath
    }
  }

  const primaryPath =
    stagePaths['fresh_path'] ??
    stagePaths['healed_path'] ??
    stagePaths['stencil_path'] ??
    stagePaths['reference_path'] ??
    ''

  if (!primaryPath) {
    return { error: 'No photos could be copied from this session' }
  }

  const styleTagIds = Array.isArray(project.style_tag_ids) ? (project.style_tag_ids as string[]) : []

  const { error: insertError } = await supabase
    .from('artist_portfolio_items')
    .insert({
      id: itemId,
      studio_id: auth.studioId,
      artist_id: project.artist_id,
      storage_path: primaryPath,
      reference_path: stagePaths['reference_path'] ?? null,
      stencil_path: stagePaths['stencil_path'] ?? null,
      fresh_path: stagePaths['fresh_path'] ?? null,
      healed_path: stagePaths['healed_path'] ?? null,
      caption: project.title,
      style_tag_ids: styleTagIds,
      is_featured: false,
      linked_project_id: projectId,
    })

  if (insertError) {
    return { error: 'Failed to create portfolio item' }
  }

  await logAuditAction(
    auth.user.authId,
    'portfolio_item.pulled_from_session',
    { type: 'artist_portfolio_items', id: itemId },
    { project_id: projectId },
    auth.studioId,
  )

  return {
    itemId,
    photosCopied: Object.keys(stagePaths).length,
    styleTagIds,
    artistId: project.artist_id,
    clientId: project.client_id ?? null,
    linkedProjectId: projectId,
  }
}

// ── addProgressionPhoto ───────────────────────────────────────────────────────

export async function addProgressionPhoto(
  itemId: string,
  stage: 'reference' | 'stencil' | 'fresh' | 'healed',
  file: File,
): Promise<{ success: true } | { success: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  if (!file || file.size === 0) return { success: false, error: 'No file provided' }

  const supabase = await createClient()

  // Verify item belongs to this studio
  const { data: item } = await supabase
    .from('artist_portfolio_items')
    .select('id, artist_id')
    .eq('id', itemId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!item) return { success: false, error: 'Item not found' }

  const PORTFOLIO_BUCKET = 'artist-portfolio'
  const ext = file.name.split('.').pop()?.toLowerCase() ?? 'jpg'
  const path = `${auth.studioId}/${item.artist_id}/${itemId}-${stage}.${ext}`

  const bytes = new Uint8Array(await file.arrayBuffer())
  const { error: uploadError } = await supabase.storage
    .from(PORTFOLIO_BUCKET)
    .upload(path, bytes, { contentType: file.type, upsert: true })

  if (uploadError) return { success: false, error: 'Upload failed' }

  const colName = `${stage}_path`
  const update: Record<string, string | null> = { [colName]: path }
  if (stage === 'healed') update['healed_at'] = new Date().toISOString().slice(0, 10)

  const { error: updateError } = await supabase
    .from('artist_portfolio_items')
    .update(update)
    .eq('id', itemId)
    .eq('studio_id', auth.studioId)

  if (updateError) return { success: false, error: updateError.message }

  return { success: true }
}

