/**
 * POST /api/flash/[id]/reserve
 *
 * Public route — no auth required.
 * Rate-limited via publicBookingCreateRatelimit (10/10min per IP).
 * Anonymous Supabase client — RLS flash_pieces_public_read enforces visibility + status.
 *
 * Creates a Dodo Payments checkout session for flash piece deposit.
 * Returns { checkoutUrl } on success.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { getDodoClient } from '@/lib/dodo/client'
import { publicBookingCreateRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

const ReserveBodySchema = z.object({
  clientEmail: z.string().email(),
  clientName: z.string().min(1).max(120),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function POST(req: NextRequest, ctx: RouteContext): Promise<NextResponse> {
  const { id: pieceId } = await ctx.params

  // Rate limit — per IP, reuse publicBookingCreateRatelimit (10/10min)
  const ip = getClientIp(req)
  const rl = await publicBookingCreateRatelimit.limit(`flash-reserve:${ip}`)
  if (!rl.success) {
    return NextResponse.json(
      { error: 'Too many requests. Please wait before trying again.' },
      { status: 429 },
    )
  }

  // Parse body
  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ReserveBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors[0]?.message ?? 'Invalid input' },
      { status: 400 },
    )
  }

  const { clientEmail, clientName } = parsed.data

  // Fetch piece (anonymous client — RLS allows public pieces only)
  const supabase = await createClient()
  const { data: piece, error: pieceErr } = await supabase
    .from('flash_pieces')
    .select(`
      id, studio_id, deposit_cents, price_cents, currency,
      status, visibility, title,
      studio:studios(id, name, slug)
    `)
    .eq('id', pieceId)
    .eq('visibility', 'public')
    .eq('status', 'available')
    .maybeSingle()

  if (pieceErr || !piece) {
    return NextResponse.json({ error: 'Flash piece not available for reservation' }, { status: 404 })
  }

  if (piece.status !== 'available') {
    return NextResponse.json({ error: 'This piece is no longer available' }, { status: 409 })
  }

  const studio = Array.isArray(piece.studio) ? piece.studio[0] : piece.studio
  const studioSlug = (studio as { slug: string } | null)?.slug ?? ''
  const siteUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://inkos.studio'

  // Create Dodo checkout
  try {
    const dodo = getDodoClient()

    // Ad-hoc amount checkout — deposit_cents per piece
    const session = await (dodo as unknown as {
      payments: {
        create: (body: Record<string, unknown>) => Promise<{ payment_link: string }>
      }
    }).payments.create({
      billing: {
        city: 'N/A',
        country: 'US',
        state: 'N/A',
        street: 'N/A',
        zipcode: '00000',
      },
      customer: {
        email: clientEmail,
        name: clientName,
      },
      product_cart: [
        {
          product_id: process.env.DODO_PRODUCT_FLASH_DEPOSIT ?? 'flash_deposit',
          quantity: 1,
          unit_amount: piece.deposit_cents > 0 ? piece.deposit_cents : piece.price_cents,
          name: `Reserve: ${piece.title}`,
        },
      ],
      return_url: `${siteUrl}/p/${studioSlug}/flash/${pieceId}?reserved=1`,
      metadata: {
        kind: 'flash_reserve',
        studioId: piece.studio_id,
        flash_piece_id: pieceId,
        client_email: clientEmail,
        client_name: clientName,
      },
    })

    return NextResponse.json({ checkoutUrl: session.payment_link, pieceId })
  } catch (err) {
    logger.error({ err, pieceId }, 'flash reserve: Dodo checkout creation failed')
    return NextResponse.json({ error: 'Payment setup failed. Please try again.' }, { status: 500 })
  }
}

/**
 * GET  /api/flash/[id] — public read (anonymous client, RLS filters)
 * PATCH /api/flash/[id] — studio-write only via RLS (authenticated)
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

const PatchSchema = z.object({
  title: z.string().min(1).max(120).optional(),
  description: z.string().max(500).optional().nullable(),
  price_cents: z.number().int().min(0).optional(),
  deposit_cents: z.number().int().min(0).optional(),
  visibility: z.enum(['public', 'private']).optional(),
  is_featured: z.boolean().optional(),
  status: z.enum(['available', 'reserved', 'sold', 'retired', 'draft']).optional(),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(req: NextRequest, ctx: RouteContext): Promise<NextResponse> {
  const { id } = await ctx.params

  const ip = getClientIp(req)
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const supabase = await createClient()
  const { data, error } = await supabase
    .from('flash_pieces')
    .select(`
      id, studio_id, artist_id, sheet_id, title, description,
      watermarked_path, price_cents, deposit_cents, currency,
      status, is_one_of_one, session_length, size_inches, placement,
      style_tag_ids, view_count, visibility, is_featured,
      artist:artists(id, display_name, slug, avatar_url),
      sheet:flash_sheets(id, title, slug)
    `)
    .eq('id', id)
    .maybeSingle()

  if (error) {
    logger.error({ error, id }, 'GET /api/flash/[id]: query failed')
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }
  if (!data) return NextResponse.json({ error: 'Not found' }, { status: 404 })

  return NextResponse.json({ piece: data })
}

export async function PATCH(req: NextRequest, ctx: RouteContext): Promise<NextResponse> {
  const { id } = await ctx.params

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Invalid' }, { status: 400 })
  }

  const supabase = await createClient()

  // RLS enforces studio_members write access — no explicit session check needed here
  const { error } = await supabase
    .from('flash_pieces')
    .update(parsed.data)
    .eq('id', id)

  if (error) {
    if (error.code === '42501') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }
    logger.error({ error, id }, 'PATCH /api/flash/[id]: update failed')
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ success: true })
}

/**
 * POST /api/flash/[id]/view — fire-and-forget view count increment.
 * Public route. Rate-limited per IP via apiRatelimit.
 * Client fires this on mount of the flash piece detail page.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'

export const dynamic = 'force-dynamic'

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function POST(req: NextRequest, ctx: RouteContext): Promise<NextResponse> {
  const { id } = await ctx.params

  // Rate limit 1 view per IP per minute per piece
  const ip = getClientIp(req)
  const rl = await apiRatelimit.limit(`view:${ip}:${id}`)
  if (!rl.success) {
    // Silently return success — rate limit on views is not a user-visible error
    return NextResponse.json({ ok: true })
  }

  // Increment — RPC call would be cleanest but a direct update is acceptable here
  // since view_count is not audit-critical
  const supabase = await createClient()
  await supabase.rpc('increment_flash_view_count' as never, { p_piece_id: id } as never)
    .catch(() => {
      // Fallback: direct update
      supabase
        .from('flash_pieces')
        .update({ view_count: 0 } as never) // will be incremented by DB
        .eq('id', id)
    })

  return NextResponse.json({ ok: true })
}

/**
 * GET /api/portfolio/pull-candidates
 * Returns completed projects (last 90d, with photos) eligible for portfolio pull.
 * Authenticated — uses RLS session client.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { listPullCandidates } from '@/lib/portfolio/queries'

export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest): Promise<NextResponse> {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = getClientIp(req)
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()
  const candidates = await listPullCandidates(supabase, auth.studioId)

  return NextResponse.json({ candidates })
}

/**
 * POST /api/ai/flash-tag
 * Claude vision auto-tagger for flash pieces.
 *
 * Authenticated: studio member only.
 * Feature-gated: ai_design (Pro+).
 * Rate-limited: expensiveRatelimit (10/min per IP).
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { requireFeatureRpc } from '@/lib/billing/feature-gate'
import { tagFlashImage } from '@/lib/ai/flash-vision'
import { AiBudgetExceededError, nextUtcMidnight } from '@/lib/ai/budget'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

const FlashTagRequestSchema = z.object({
  imageUrl: z.string().url(),
  studioId: z.string().uuid(),
  pieceId: z.string().uuid().optional(),
})

export async function POST(req: NextRequest): Promise<NextResponse> {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = getClientIp(req)
  const rl = await expensiveRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = FlashTagRequestSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors[0]?.message ?? 'Invalid input' },
      { status: 400 },
    )
  }

  const { imageUrl, studioId, pieceId } = parsed.data

  // Studio ownership cross-check
  if (studioId !== auth.studioId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
  }

  const supabase = await createClient()

  // Feature gate — ai_design (Pro+)
  try {
    await requireFeatureRpc(supabase, studioId, 'ai_design')
  } catch {
    return NextResponse.json({ error: 'feature_locked' }, { status: 403 })
  }

  try {
    const result = await tagFlashImage(supabase, { imageUrl, studioId, pieceId })
    return NextResponse.json(result)
  } catch (err) {
    if (err instanceof AiBudgetExceededError) {
      return NextResponse.json(
        { error: 'ai_budget_exceeded', resetAt: nextUtcMidnight() },
        { status: 429 },
      )
    }
    logger.error({ err, studioId, imageUrl }, 'flash-tag: tagging failed')
    return NextResponse.json({ error: 'AI tagging failed' }, { status: 500 })
  }
}

