// --- flash reserve: payment.succeeded (Sprint 13) ───────────────────────────
// Sequence per Arya integration spec §4.2.
async function handleFlashReserveSucceeded(
  data: z.infer<typeof PaymentSchema>,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  // 1. Validate metadata shape (defense-in-depth)
  const m = data.metadata
  if (!isFlashReserveMetadata(m)) {
    logger.warn({ paymentId: data.id, metadata: m }, 'flash_reserve: invalid metadata shape')
    return // Silent skip — don't 500, don't cause Dodo to retry-storm
  }

  const { studioId, flash_piece_id: pieceId, client_email, client_name } = m

  // 2. Idempotency — if a payment row with this dodo_payment_id already has booking_id, skip
  const { data: existingPayment } = await supabase
    .from('payments')
    .select('id, booking_id')
    .eq('dodo_payment_id', data.id)
    .maybeSingle()

  if (existingPayment?.booking_id) {
    logger.info({ paymentId: data.id, pieceId }, 'flash_reserve: already processed')
    return
  }

  // 3. Look up or create client (email-keyed within studio)
  let clientId: string
  const { data: existingClient } = await supabase
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('email', client_email)
    .maybeSingle()

  if (existingClient) {
    clientId = existingClient.id
  } else {
    const nameParts = client_name.split(' ')
    const firstName = nameParts[0] ?? client_name
    const lastName = nameParts.slice(1).join(' ') || null

    const { data: newClient, error: clientErr } = await supabase
      .from('clients')
      .insert({
        studio_id: studioId,
        email: client_email,
        first_name: firstName,
        last_name: lastName,
        source: 'flash_reserve',
      })
      .select('id')
      .single()

    if (clientErr) throw new Error(`flash_reserve: create client failed: ${clientErr.message}`)
    clientId = newClient.id
  }

  // 4. Fetch piece to get artist + studio cross-check
  const { data: piece, error: pieceErr } = await supabase
    .from('flash_pieces')
    .select('artist_id, title, studio_id, deposit_cents, currency, session_length')
    .eq('id', pieceId)
    .single()

  if (pieceErr || !piece) {
    throw new Error(`flash_reserve: piece ${pieceId} not found`)
  }

  if (piece.studio_id !== studioId) {
    logger.error(
      { pieceId, metaStudio: studioId, pieceStudio: piece.studio_id },
      'flash_reserve: studio mismatch — refusing',
    )
    return // Do NOT process — possible data tampering
  }

  // 5. Create draft booking
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .insert({
      studio_id: studioId,
      artist_id: piece.artist_id,
      client_id: clientId,
      status: 'pending_artist_review',
      type: 'flash_reserve',
      title: piece.title,
      deposit_cents: piece.deposit_cents,
      deposit_paid: true,
      deposit_paid_at: data.succeeded_at ?? new Date().toISOString(),
      deposit_payment_id: data.id,
      currency: piece.currency,
      metadata: { flash_piece_id: pieceId } as unknown as Json,
    })
    .select('id')
    .single()

  if (bookingErr) throw new Error(`flash_reserve: create booking failed: ${bookingErr.message}`)

  // 6. Atomic reservation — race-safe RPC
  try {
    await reserveFlashPiece(supabase, {
      p_piece_id: pieceId,
      p_client_id: clientId,
      p_booking_id: booking.id,
    })
  } catch (e) {
    if (e instanceof FlashPieceUnavailableError) {
      // RACE CONDITION: piece was reserved between checkout and webhook
      // Strategy: cancel booking + auto-refund + alert studio owner
      await supabase
        .from('bookings')
        .update({
          status: 'cancelled',
          metadata: { cancellation_reason: 'flash_piece_unavailable', flash_piece_id: pieceId } as unknown as Json,
        })
        .eq('id', booking.id)

      // Enqueue async refund (non-blocking)
      try {
        await enqueueJob('dodo-refund', {
          paymentId: data.id,
          amountCents: data.amount,
          reason: 'flash_piece_already_reserved',
          studioId,
          clientId,
          pieceId,
        })

        // Alert studio owner
        const ownerEmail = await resolveOwnerEmail(studioId, supabase)
        if (ownerEmail) {
          await enqueueJob('send-email', {
            to: ownerEmail,
            template: 'flash_reserve_race_lost',
            data: {
              pieceTitle: piece.title,
              clientEmail: client_email,
              refundAmountCents: data.amount,
              studioId,
            } as Record<string, unknown>,
          })
        }
      } catch (enqueueErr) {
        logger.error({ enqueueErr }, 'flash_reserve: failed to enqueue refund/email after race')
      }

      logger.warn({ pieceId, paymentId: data.id }, 'flash_reserve: race condition — auto-refund queued')
      return
    }
    throw e
  }

  // 7. Insert payment row (upsert for idempotency)
  await supabase.from('payments').upsert(
    {
      studio_id: studioId,
      dodo_payment_id: data.id,
      dodo_checkout_id: data.checkout_id ?? null,
      booking_id: booking.id,
      client_id: clientId,
      type: 'deposit',
      amount_cents: data.amount,
      currency: data.currency ?? 'USD',
      status: 'succeeded',
      succeeded_at: data.succeeded_at ?? new Date().toISOString(),
      metadata: { ...data.metadata, flash_piece_id: pieceId } as unknown as Json,
    },
    { onConflict: 'dodo_payment_id' },
  )

  // 8. Fetch studio for slug (ISR revalidation + artist profile page)
  const { data: studioRow } = await supabase
    .from('studios')
    .select('name, slug')
    .eq('id', studioId)
    .maybeSingle()

  // 9. Send Resend emails (queued, non-blocking)
  try {
    await enqueueJob('send-email', {
      to: client_email,
      template: 'flash_reserve_confirmed_client',
      data: {
        clientName: client_name,
        pieceTitle: piece.title,
        bookingId: booking.id,
        studioId,
        studioName: studioRow?.name ?? '',
      } as Record<string, unknown>,
    })

    const ownerEmail = await resolveOwnerEmail(studioId, supabase)
    if (ownerEmail) {
      await enqueueJob('send-email', {
        to: ownerEmail,
        template: 'flash_reserve_alert_studio',
        data: {
          pieceTitle: piece.title,
          clientName: client_name,
          clientEmail: client_email,
          bookingId: booking.id,
          studioId,
        } as Record<string, unknown>,
      })
    }
  } catch (emailErr) {
    logger.warn({ emailErr }, 'flash_reserve: failed to enqueue confirmation emails')
  }

  // 10. ISR revalidation — bust cached public pages
  if (studioRow?.slug) {
    try {
      await enqueueJob('revalidate-path', {
        paths: [
          `/p/${studioRow.slug}/flash/${pieceId}`,
          `/p/${studioRow.slug}`,
        ],
      })
    } catch {
      // Non-critical
    }
  }

  logger.info({ pieceId, bookingId: booking.id, paymentId: data.id }, 'flash_reserve: completed')
}

