/**
 * flash-bulk-upload BullMQ worker.
 *
 * Consumes 'flash-bulk-upload' queue.
 * Per file: staging download → AI tag → watermark → insert as draft.
 * Emits Realtime Broadcast on flash:bulk:{uploadId} with FlashBulkProgressEvent.
 *
 * Concurrency: 2 (CPU/network-bound: Claude vision + sharp)
 * Attempts: 3, exponential backoff 5s
 * Per-file timeout: 30s
 */
import { Worker } from 'bullmq'
import { createClient } from '@supabase/supabase-js'
import type { FlashBulkProgressEvent } from '../../lib/realtime/flash-bulk'
import { logger } from '../lib/logger'
import { workerEnv } from '../lib/env'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'flash-bulk-upload'
const FLASH_BUCKET = 'flash-pieces'

// ── Payload type ───────────────────────────────────────────────────────────────

interface FlashBulkUploadPayload {
  uploadId: string
  studioId: string
  artistId: string
  sheetId: string | null
  files: Array<{
    tempPath: string
    originalName: string
    mimeType: 'image/png' | 'image/jpeg' | 'image/webp'
    sizeBytes: number
  }>
  triggeredByUserId: string
}

function isFlashBulkPayload(data: unknown): data is FlashBulkUploadPayload {
  if (typeof data !== 'object' || data === null) return false
  const d = data as Record<string, unknown>
  return (
    typeof d['uploadId'] === 'string' &&
    typeof d['studioId'] === 'string' &&
    typeof d['artistId'] === 'string' &&
    Array.isArray(d['files'])
  )
}

// ── Supabase service-role client ───────────────────────────────────────────────

function getSupabase() {
  return createClient(
    workerEnv.NEXT_PUBLIC_SUPABASE_URL,
    workerEnv.SUPABASE_SERVICE_ROLE_KEY,
    { auth: { autoRefreshToken: false, persistSession: false } },
  )
}

// ── Realtime broadcast helper ──────────────────────────────────────────────────

async function broadcastProgress(
  supabase: ReturnType<typeof getSupabase>,
  channelName: string,
  event: FlashBulkProgressEvent,
): Promise<void> {
  try {
    const channel = supabase.channel(channelName)
    await channel.send({
      type: 'broadcast',
      event: 'progress',
      payload: event,
    })
  } catch (err) {
    logger.warn({ err, channelName }, 'flash-bulk: broadcast failed')
  }
}

// ── Worker ─────────────────────────────────────────────────────────────────────

export function createFlashBulkUploadWorker() {
  const redisUrl = workerEnv.REDIS_URL
  if (!redisUrl) {
    logger.warn('flash-bulk-upload: REDIS_URL not set — worker not started')
    return {
      close: async () => undefined,
    }
  }

  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isFlashBulkPayload(job.data)) {
        logger.error({ jobId: job.id }, 'flash-bulk: invalid payload')
        return
      }

      const payload = job.data
      const supabase = getSupabase()
      const channelName = `flash:bulk:${payload.uploadId}`
      const total = payload.files.length

      await broadcastProgress(supabase, channelName, {
        type: 'started',
        uploadId: payload.uploadId,
        total,
      })

      const succeededPieceIds: string[] = []
      let failedCount = 0

      for (let i = 0; i < payload.files.length; i++) {
        const file = payload.files[i]
        if (!file) continue

        await broadcastProgress(supabase, channelName, {
          type: 'progress',
          uploadId: payload.uploadId,
          completed: i,
          total,
          currentFile: file.originalName,
        })

        try {
          // 1. Download from staging
          const { data: fileData, error: dlErr } = await supabase.storage
            .from(FLASH_BUCKET)
            .download(file.tempPath)

          if (dlErr || !fileData) {
            throw new Error(`staging download failed: ${dlErr?.message ?? 'no data'}`)
          }

          const imageBuffer = Buffer.from(await fileData.arrayBuffer())

          // 2. AI tag (best-effort — don't fail bulk on tag error)
          let title = file.originalName.replace(/\.[^.]+$/, '').slice(0, 60)
          let styleTags: string[] = []
          const supabaseUrl = workerEnv.NEXT_PUBLIC_SUPABASE_URL ?? ''
          const tempPublicUrl = `${supabaseUrl}/storage/v1/object/public/${FLASH_BUCKET}/${file.tempPath}`

          try {
            // Dynamic import of flash-vision — avoids bundling Anthropic in all workers
            const { tagFlashImage } = await import('../../lib/ai/flash-vision')
            const tagResult = await tagFlashImage(supabase as never, {
              imageUrl: tempPublicUrl,
              studioId: payload.studioId,
            })
            title = tagResult.title || title
            styleTags = tagResult.styleTagIds
          } catch (tagErr) {
            logger.warn({ tagErr, file: file.originalName }, 'flash-bulk: AI tag failed — continuing')
          }

          // 3. Watermark (best-effort)
          const pieceId = crypto.randomUUID()
          const ext = file.originalName.split('.').pop()?.toLowerCase() ?? 'jpg'
          const origPath = `${payload.studioId}/originals/${pieceId}.${ext}`
          const wmPath = `${payload.studioId}/watermarked/${pieceId}.${ext}`

          // Fetch studio logo for watermark
          let logoUrl: string | null = null
          const { data: studioRow } = await supabase
            .from('studios')
            .select('brand_logo_url')
            .eq('id', payload.studioId)
            .maybeSingle()
          logoUrl = (studioRow as { brand_logo_url: string | null } | null)?.brand_logo_url ?? null

          let watermarkedBuffer = imageBuffer
          try {
            const { applyWatermark } = await import('../../lib/ai/watermark')
            const wmResult = await applyWatermark({
              imageBuffer,
              logoUrl,
              pieceId,
              studioId: payload.studioId,
              ext: ext as 'jpg' | 'jpeg' | 'png' | 'webp',
            })
            watermarkedBuffer = wmResult.buffer
          } catch (wmErr) {
            logger.warn({ wmErr }, 'flash-bulk: watermark failed — using original')
          }

          // 4. Upload originals + watermarked
          const [origUpload, wmUpload] = await Promise.all([
            supabase.storage
              .from(FLASH_BUCKET)
              .upload(origPath, imageBuffer, { contentType: file.mimeType }),
            supabase.storage
              .from(FLASH_BUCKET)
              .upload(wmPath, watermarkedBuffer, { contentType: file.mimeType }),
          ])

          if (origUpload.error) throw new Error(`orig upload failed: ${origUpload.error.message}`)

          // 5. Insert as draft
          const { error: insertErr } = await supabase.from('flash_pieces').insert({
            id: pieceId,
            studio_id: payload.studioId,
            artist_id: payload.artistId,
            sheet_id: payload.sheetId,
            title,
            storage_path: origPath,
            watermarked_path: wmUpload.error ? null : wmPath,
            price_cents: 0, // owner fills in after bulk upload
            currency: 'USD',
            deposit_cents: 0,
            session_length: '1h',
            style_tag_ids: styleTags,
            is_one_of_one: false,
            status: 'draft',
            visibility: 'private',
            is_featured: false,
            ai_tagged_at: styleTags.length > 0 ? new Date().toISOString() : null,
            created_by: payload.triggeredByUserId,
          })

          if (insertErr) throw new Error(`insert failed: ${insertErr.message}`)

          // 6. Delete staging file
          await supabase.storage.from(FLASH_BUCKET).remove([file.tempPath]).catch(() => undefined)

          succeededPieceIds.push(pieceId)
        } catch (fileErr) {
          failedCount++
          logger.error({ fileErr, file: file.originalName }, 'flash-bulk: file processing failed')

          await broadcastProgress(supabase, channelName, {
            type: 'fileError',
            uploadId: payload.uploadId,
            fileIndex: i,
            fileName: file.originalName,
            error: fileErr instanceof Error ? fileErr.message : 'Unknown error',
          })
        }
      }

      await broadcastProgress(supabase, channelName, {
        type: 'completed',
        uploadId: payload.uploadId,
        succeeded: succeededPieceIds.length,
        failed: failedCount,
        pieceIds: succeededPieceIds,
      })

      logger.info(
        { uploadId: payload.uploadId, succeeded: succeededPieceIds.length, failed: failedCount },
        'flash-bulk: completed',
      )
    },
    {
      connection: {
        url: redisUrl,
        maxRetriesPerRequest: null,
      },
      concurrency: 2,
    },
  )

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'flash-bulk-upload: job failed')
  })

  return worker
}

