'use client'

/**
 * Subscribe to flash_pieces postgres_changes for a studio.
 * Per Arya integration spec §3.2.
 *
 * Channel: studio:{studioId}:flash_pieces (postgres_changes, RLS-scoped)
 * Calls onUpdate when any INSERT/UPDATE/DELETE occurs, so the calling
 * component can invalidate its query cache.
 */
import { useEffect, useRef } from 'react'
import { createBrowserClient } from '@supabase/ssr'

interface UseFlashPiecesRealtimeOptions {
  studioId: string
  onUpdate: () => void
}

export function useFlashPiecesRealtime({ studioId, onUpdate }: UseFlashPiecesRealtimeOptions): void {
  const onUpdateRef = useRef(onUpdate)
  onUpdateRef.current = onUpdate

  useEffect(() => {
    if (!studioId) return

    const supabase = createBrowserClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    )

    const channel = supabase
      .channel(`studio:${studioId}:flash_pieces`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'flash_pieces',
          filter: `studio_id=eq.${studioId}`,
        },
        () => {
          onUpdateRef.current()
        },
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel).catch(() => undefined)
    }
  }, [studioId])
}

'use client'

/**
 * Subscribe to Realtime Broadcast for bulk flash upload progress.
 * Per Arya integration spec §3.1.
 *
 * Channel: flash:bulk:{uploadId} (Broadcast — ephemeral, no RLS)
 * Direction: worker → client
 */
import { useEffect, useRef, useState } from 'react'
import { createBrowserClient } from '@supabase/ssr'
import type { FlashBulkProgressEvent } from '@/lib/realtime/flash-bulk'

export interface BulkUploadState {
  completed: number
  total: number
  currentFile: string
  status: 'idle' | 'running' | 'completed' | 'aborted'
  failedCount: number
  succeededPieceIds: string[]
}

const INITIAL_STATE: BulkUploadState = {
  completed: 0,
  total: 0,
  currentFile: '',
  status: 'idle',
  failedCount: 0,
  succeededPieceIds: [],
}

export function useBulkUploadProgress(uploadId: string | null): BulkUploadState {
  const [state, setState] = useState<BulkUploadState>(INITIAL_STATE)
  const stateRef = useRef(state)
  stateRef.current = state

  useEffect(() => {
    if (!uploadId) {
      setState(INITIAL_STATE)
      return
    }

    const supabase = createBrowserClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    )

    const channel = supabase
      .channel(`flash:bulk:${uploadId}`)
      .on('broadcast', { event: 'progress' }, ({ payload }: { payload: FlashBulkProgressEvent }) => {
        switch (payload.type) {
          case 'started':
            setState({
              completed: 0,
              total: payload.total,
              currentFile: '',
              status: 'running',
              failedCount: 0,
              succeededPieceIds: [],
            })
            break
          case 'progress':
            setState((prev) => ({
              ...prev,
              completed: payload.completed,
              total: payload.total,
              currentFile: payload.currentFile,
              status: 'running',
            }))
            break
          case 'fileError':
            setState((prev) => ({
              ...prev,
              failedCount: prev.failedCount + 1,
            }))
            break
          case 'completed':
            setState((prev) => ({
              ...prev,
              completed: payload.succeeded + payload.failed,
              total: payload.succeeded + payload.failed,
              status: 'completed',
              failedCount: payload.failed,
              succeededPieceIds: payload.pieceIds,
            }))
            break
          case 'aborted':
            setState((prev) => ({
              ...prev,
              status: 'aborted',
            }))
            break
        }
      })
      .subscribe()

    return () => {
      supabase.removeChannel(channel).catch(() => undefined)
    }
  }, [uploadId])

  return state
}

'use client'

/**
 * Flash ↔ Portfolio mode toggle.
 * Updates URL search param: /portfolio?mode=flash|portfolio.
 * Per Vega spec Component 2.
 */
import { useRouter } from 'next/navigation'

interface ModeToggleProps {
  currentMode: 'flash' | 'portfolio'
}

export function ModeToggle({ currentMode }: ModeToggleProps) {
  const router = useRouter()

  function switchMode(mode: 'flash' | 'portfolio') {
    if (mode === currentMode) return
    const params = new URLSearchParams(window.location.search)
    params.set('mode', mode)
    router.replace(`/portfolio?${params.toString()}`)
  }

  return (
    <div
      role="tablist"
      aria-label="Portfolio mode"
      className="inline-flex items-center rounded-full bg-muted p-0.5 border border-border"
    >
      <button
        role="tab"
        type="button"
        aria-selected={currentMode === 'flash'}
        aria-controls="portfolio-grid"
        onClick={() => switchMode('flash')}
        className={[
          'rounded-full px-4 py-1.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
          currentMode === 'flash'
            ? 'bg-card text-foreground shadow-soft'
            : 'text-muted-foreground hover:text-foreground',
        ].join(' ')}
      >
        Flash
      </button>
      <button
        role="tab"
        type="button"
        aria-selected={currentMode === 'portfolio'}
        aria-controls="portfolio-grid"
        onClick={() => switchMode('portfolio')}
        className={[
          'rounded-full px-4 py-1.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
          currentMode === 'portfolio'
            ? 'bg-card text-foreground shadow-soft'
            : 'text-muted-foreground hover:text-foreground',
        ].join(' ')}
      >
        Portfolio
      </button>
    </div>
  )
}

'use client'

/**
 * Saved views row — preset quick-filter chips + custom saved views.
 * Per Vega spec Component 3.
 */
import { Plus, X } from 'lucide-react'
import { PRESET_VIEWS, type SavedView } from '@/lib/portfolio/saved-views'

interface SavedViewsRowProps {
  activeViewId: string | null
  customViews: SavedView[]
  onSelect: (viewId: string | null) => void
  onDelete: (viewId: string) => void
  onNew: () => void
}

export function SavedViewsRow({
  activeViewId,
  customViews,
  onSelect,
  onDelete,
  onNew,
}: SavedViewsRowProps) {
  const allViews = [...PRESET_VIEWS, ...customViews]

  return (
    <div
      role="toolbar"
      aria-label="Saved views"
      className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none -webkit-overflow-scrolling-touch"
    >
      {allViews.map((view) => {
        const isActive = activeViewId === view.id || (activeViewId === null && view.id === 'all')
        const isPreset = PRESET_VIEWS.some((p) => p.id === view.id)

        return (
          <div key={view.id} className="relative shrink-0 group/chip">
            <button
              role="button"
              type="button"
              aria-pressed={isActive}
              onClick={() => onSelect(view.id === 'all' ? null : view.id)}
              className={[
                'rounded-full px-3 py-1 text-xs font-medium border transition-colors whitespace-nowrap focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                isActive
                  ? 'bg-foreground text-primary-foreground border-foreground'
                  : 'bg-card text-muted-foreground border-border hover:border-foreground hover:text-foreground',
              ].join(' ')}
            >
              {view.label}
            </button>
            {!isPreset && (
              <button
                type="button"
                aria-label={`Delete saved view: ${view.label}`}
                onClick={(e) => {
                  e.stopPropagation()
                  onDelete(view.id)
                }}
                className="absolute -top-1 -right-1 hidden group-hover/chip:flex items-center justify-center w-4 h-4 rounded-full bg-foreground text-primary-foreground hover:opacity-80"
              >
                <X className="w-2.5 h-2.5" />
              </button>
            )}
          </div>
        )
      })}

      <button
        type="button"
        aria-label="Create new saved view"
        onClick={onNew}
        className="shrink-0 inline-flex items-center gap-1 rounded-full px-3 py-1 text-xs font-medium border border-dashed border-border text-muted-foreground hover:border-foreground hover:text-foreground transition-colors whitespace-nowrap focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <Plus className="w-3 h-3" />
        New view
      </button>
    </div>
  )
}

'use client'

/**
 * Portfolio toolbar — search + filter popovers + sort + view density.
 * Per Vega spec Component 4.
 */
import { Search, ChevronDown, X, Grid3x3, LayoutGrid } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import type { FlashStatus, SortOption, ViewDensity } from '@/lib/portfolio/saved-views'

const STYLE_OPTIONS = [
  'Black & grey',
  'Fine line',
  'Neo-trad',
  'Traditional',
  'Color',
  'Japanese',
  'Script',
]

const PLACEMENT_OPTIONS = ['Arm', 'Leg', 'Back', 'Chest', 'Hand', 'Neck', 'Other']
const STATUS_OPTIONS: { value: FlashStatus; label: string }[] = [
  { value: 'available', label: 'Available' },
  { value: 'reserved', label: 'Reserved' },
  { value: 'sold', label: 'Sold' },
  { value: 'retired', label: 'Retired' },
]

interface PortfolioToolbarProps {
  mode: 'flash' | 'portfolio'
  search: string
  styleTags: string[]
  statuses: FlashStatus[]
  placements: string[]
  artistId: string | null
  sort: SortOption
  density: ViewDensity
  artists: Array<{ id: string; display_name: string }>
  onSearchChange: (v: string) => void
  onStyleTagsChange: (v: string[]) => void
  onStatusesChange: (v: FlashStatus[]) => void
  onPlacementsChange: (v: string[]) => void
  onArtistChange: (v: string | null) => void
  onSortChange: (v: SortOption) => void
  onDensityChange: (v: ViewDensity) => void
  onClearAll: () => void
}

export function PortfolioToolbar({
  mode,
  search,
  styleTags,
  statuses,
  placements,
  artistId,
  sort,
  density,
  artists,
  onSearchChange,
  onStyleTagsChange,
  onStatusesChange,
  onPlacementsChange,
  onArtistChange,
  onSortChange,
  onDensityChange,
  onClearAll,
}: PortfolioToolbarProps) {
  const hasFilters =
    styleTags.length > 0 || statuses.length > 0 || placements.length > 0 || artistId !== null || search !== ''

  function toggleMulti<T extends string>(
    arr: T[],
    val: T,
    setter: (v: T[]) => void,
  ) {
    if (arr.includes(val)) {
      setter(arr.filter((v) => v !== val))
    } else {
      setter([...arr, val])
    }
  }

  return (
    <div className="space-y-2">
      {/* Main toolbar row */}
      <div className="flex items-center gap-2 flex-wrap">
        {/* Search */}
        <div role="search" className="relative w-56">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
          <Input
            type="search"
            placeholder="Search pieces…"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
            className="pl-8 pr-8 h-9 text-sm"
            aria-label="Search flash pieces"
          />
        </div>

        {/* Style filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              aria-haspopup="listbox"
              className="h-9 text-sm"
            >
              {styleTags.length > 0 ? `Style · ${styleTags.length}` : 'Style'}
              <ChevronDown className="ml-1 w-3.5 h-3.5" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-48 p-2" align="start">
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground px-2 py-1">Style</p>
            {STYLE_OPTIONS.map((s) => (
              <button
                key={s}
                type="button"
                role="option"
                aria-selected={styleTags.includes(s)}
                onClick={() => toggleMulti(styleTags, s, onStyleTagsChange)}
                className={[
                  'w-full text-left text-sm px-2 py-1.5 rounded-sm transition-colors flex items-center gap-2',
                  styleTags.includes(s) ? 'bg-muted text-foreground font-medium' : 'text-foreground hover:bg-muted/60',
                ].join(' ')}
              >
                <span className={`w-3 h-3 rounded-sm border ${styleTags.includes(s) ? 'bg-foreground border-foreground' : 'border-border'}`} />
                {s}
              </button>
            ))}
          </PopoverContent>
        </Popover>

        {/* Status filter (flash mode only) */}
        {mode === 'flash' && (
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" aria-haspopup="listbox" className="h-9 text-sm">
                {statuses.length > 0 ? `Status · ${statuses.length}` : 'Status'}
                <ChevronDown className="ml-1 w-3.5 h-3.5" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-44 p-2" align="start">
              <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground px-2 py-1">Status</p>
              {STATUS_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  role="option"
                  aria-selected={statuses.includes(opt.value)}
                  onClick={() => toggleMulti(statuses, opt.value, onStatusesChange)}
                  className={[
                    'w-full text-left text-sm px-2 py-1.5 rounded-sm transition-colors flex items-center gap-2',
                    statuses.includes(opt.value) ? 'bg-muted text-foreground font-medium' : 'text-foreground hover:bg-muted/60',
                  ].join(' ')}
                >
                  <span className={`w-3 h-3 rounded-sm border ${statuses.includes(opt.value) ? 'bg-foreground border-foreground' : 'border-border'}`} />
                  {opt.label}
                </button>
              ))}
            </PopoverContent>
          </Popover>
        )}

        {/* Placement filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" aria-haspopup="listbox" className="h-9 text-sm">
              {placements.length > 0 ? `Placement · ${placements.length}` : 'Placement'}
              <ChevronDown className="ml-1 w-3.5 h-3.5" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-44 p-2" align="start">
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground px-2 py-1">Placement</p>
            {PLACEMENT_OPTIONS.map((p) => {
              const val = p.toLowerCase()
              return (
                <button
                  key={val}
                  type="button"
                  role="option"
                  aria-selected={placements.includes(val)}
                  onClick={() => toggleMulti(placements, val, onPlacementsChange)}
                  className={[
                    'w-full text-left text-sm px-2 py-1.5 rounded-sm transition-colors flex items-center gap-2',
                    placements.includes(val) ? 'bg-muted text-foreground font-medium' : 'text-foreground hover:bg-muted/60',
                  ].join(' ')}
                >
                  <span className={`w-3 h-3 rounded-sm border ${placements.includes(val) ? 'bg-foreground border-foreground' : 'border-border'}`} />
                  {p}
                </button>
              )
            })}
          </PopoverContent>
        </Popover>

        {/* Artist filter */}
        <Select
          value={artistId ?? 'all'}
          onValueChange={(v) => onArtistChange(v === 'all' ? null : v)}
        >
          <SelectTrigger className="h-9 w-36 text-sm" aria-label="Filter by artist">
            <SelectValue placeholder="All artists" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All artists</SelectItem>
            {artists.map((a) => (
              <SelectItem key={a.id} value={a.id}>
                {a.display_name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* Sort */}
        <Select value={sort} onValueChange={(v) => onSortChange(v as SortOption)}>
          <SelectTrigger className="h-9 w-40 text-sm" aria-label="Sort order">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="newest">Newest</SelectItem>
            <SelectItem value="oldest">Oldest</SelectItem>
            <SelectItem value="price_asc">Price: Low → High</SelectItem>
            <SelectItem value="price_desc">Price: High → Low</SelectItem>
            <SelectItem value="views">Most viewed</SelectItem>
          </SelectContent>
        </Select>

        {/* View density */}
        <div className="flex items-center gap-1 ml-auto">
          <button
            type="button"
            aria-label="Grid view"
            onClick={() => onDensityChange('grid')}
            className={[
              'p-2 rounded-md transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              density === 'grid' ? 'bg-muted text-foreground' : 'text-muted-foreground hover:text-foreground',
            ].join(' ')}
          >
            <Grid3x3 className="w-4 h-4" />
          </button>
          <button
            type="button"
            aria-label="Wall view"
            onClick={() => onDensityChange('wall')}
            className={[
              'p-2 rounded-md transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              density === 'wall' ? 'bg-muted text-foreground' : 'text-muted-foreground hover:text-foreground',
            ].join(' ')}
          >
            <LayoutGrid className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Active filter pills */}
      {hasFilters && (
        <div className="flex items-center gap-2 flex-wrap animate-in slide-in-from-top-1 fade-in-0 duration-150">
          <span className="text-[11px] font-medium text-muted-foreground">Active filters:</span>
          {styleTags.map((tag) => (
            <button
              key={tag}
              type="button"
              onClick={() => onStyleTagsChange(styleTags.filter((t) => t !== tag))}
              className="inline-flex items-center gap-1 rounded-full bg-muted border border-border text-xs text-foreground px-2.5 py-0.5 hover:bg-muted/80"
            >
              {tag}
              <X className="w-2.5 h-2.5" />
            </button>
          ))}
          {statuses.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => onStatusesChange(statuses.filter((v) => v !== s))}
              className="inline-flex items-center gap-1 rounded-full bg-muted border border-border text-xs text-foreground px-2.5 py-0.5 hover:bg-muted/80 capitalize"
            >
              {s}
              <X className="w-2.5 h-2.5" />
            </button>
          ))}
          {placements.map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => onPlacementsChange(placements.filter((v) => v !== p))}
              className="inline-flex items-center gap-1 rounded-full bg-muted border border-border text-xs text-foreground px-2.5 py-0.5 hover:bg-muted/80 capitalize"
            >
              {p}
              <X className="w-2.5 h-2.5" />
            </button>
          ))}
          <button
            type="button"
            onClick={onClearAll}
            className="text-xs text-muted-foreground hover:text-foreground transition-colors"
          >
            Clear all
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * Flash piece card — status badge, 1/1 badge, featured star, price.
 * Per Vega spec Component 5.
 */
import { Star, Edit2, Copy, Archive, RotateCcw } from 'lucide-react'
import type { FlashPieceWithRelations } from '@/lib/portfolio/queries'
import { flashPublicUrl } from '@/lib/storage/flash-paths'
import { Skeleton } from '@/components/ui/skeleton'

interface FlashCardProps {
  piece: FlashPieceWithRelations
  studioSlug: string
  isSelected: boolean
  canManage: boolean
  onClick: () => void
  onEdit: () => void
  onDuplicate: () => void
  onCopyUrl: () => void
  onArchive: () => void
}

export function FlashCard({
  piece,
  studioSlug,
  isSelected,
  canManage,
  onClick,
  onEdit,
  onDuplicate,
  onCopyUrl,
  onArchive,
}: FlashCardProps) {
  const artist = Array.isArray(piece.artist) ? piece.artist[0] : piece.artist
  const imageUrl = piece.watermarked_path
    ? flashPublicUrl(piece.watermarked_path)
    : piece.storage_path
      ? `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/artist-portfolio/${piece.storage_path}`
      : null

  const isSold = piece.status === 'sold'
  const isRetired = piece.status === 'retired'

  const price = (piece.price_cents / 100).toLocaleString('en-US', {
    style: 'currency',
    currency: piece.currency ?? 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  })

  return (
    <article
      aria-label={`${piece.title}${artist ? ` by ${artist.display_name}` : ''}, ${piece.status}, ${price}`}
      className={[
        'group relative rounded-lg bg-card border border-border shadow-card cursor-pointer overflow-hidden transition-[box-shadow,transform] duration-150 ease-out focus-within:ring-2 focus-within:ring-foreground focus-within:ring-offset-1',
        isSelected ? 'ring-2 ring-foreground ring-offset-1' : '',
        'hover:shadow-card-hover hover:-translate-y-px active:translate-y-0 active:shadow-soft',
      ].join(' ')}
    >
      {/* Image area */}
      <div className="relative aspect-[3/4] w-full bg-muted overflow-hidden">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={`${piece.title}${artist ? ` — flash piece by ${artist.display_name}` : ''}`}
            className={[
              'w-full h-full object-cover',
              isSold ? 'grayscale' : '',
              isRetired ? 'grayscale opacity-50' : '',
            ].join(' ')}
            loading="lazy"
          />
        ) : (
          <div className="w-full h-full bg-muted" />
        )}

        {/* Status badge (top-left) — not shown for retired in public, but owner sees it */}
        {piece.status !== 'retired' && piece.status !== 'draft' && (
          <span
            role="status"
            aria-label={`Status: ${piece.status}`}
            className={[
              'absolute top-2 left-2 rounded-full px-2 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em]',
              piece.status === 'available'
                ? 'bg-[var(--color-status-available)] text-[var(--color-status-available-fg)] border border-[var(--color-status-available-bd)]'
                : piece.status === 'reserved'
                  ? 'bg-[var(--color-status-reserved)] text-[var(--color-status-reserved-fg)]'
                  : 'bg-[var(--color-status-sold)] text-[var(--color-status-sold-fg)]',
            ].join(' ')}
          >
            {piece.status}
          </span>
        )}

        {/* Draft badge (owner only) */}
        {piece.status === 'draft' && canManage && (
          <span
            role="status"
            aria-label="Status: Draft"
            className="absolute top-2 left-2 rounded-full px-2 py-0.5 border border-dashed border-border text-muted-foreground text-[11px] font-bold uppercase tracking-[0.08em] bg-card/80"
          >
            Draft
          </span>
        )}

        {/* 1/1 badge + featured star (top-right) */}
        <div className="absolute top-2 right-2 flex items-center gap-1.5">
          {piece.is_featured && (
            <span aria-label="Featured piece" role="img">
              <Star className="w-3 h-3 fill-destructive text-destructive" />
            </span>
          )}
          {piece.is_one_of_one && (
            <span className="rounded-full border border-foreground bg-card px-1.5 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em] text-foreground">
              1/1
            </span>
          )}
        </div>

        {/* Hover quick-actions overlay (manager only) */}
        {canManage && (
          <div className="absolute inset-0 bg-foreground/[0.72] opacity-0 group-hover:opacity-100 transition-opacity duration-150 flex items-center justify-center">
            <div className="grid grid-cols-2 gap-2 p-3">
              {[
                { label: 'Edit', shortcut: 'E', action: onEdit, Icon: Edit2 },
                { label: 'Duplicate', shortcut: 'D', action: onDuplicate, Icon: RotateCcw },
                { label: 'Copy URL', shortcut: 'U', action: onCopyUrl, Icon: Copy },
                { label: 'Archive', shortcut: 'A', action: onArchive, Icon: Archive },
              ].map(({ label, shortcut, action, Icon }) => (
                <button
                  key={label}
                  type="button"
                  aria-label={`${label} ${piece.title}`}
                  onClick={(e) => {
                    e.stopPropagation()
                    action()
