import { Star, Edit2, Copy, Archive, RotateCcw, ImageOff } from 'lucide-react'
import type { PortfolioItemWithArtist } from '@/lib/portfolio/queries'
import { Skeleton } from '@/components/ui/skeleton'

interface PortfolioCardProps {
  item: PortfolioItemWithArtist
  styleTags: Array<{ id: string; name: string }>
  isSelected: boolean
  canManage: boolean
  onClick: () => void
  onEdit: () => void
  onDuplicate: () => void
  onCopyUrl: () => void
  onArchive: () => void
}

export function PortfolioCard({
  item,
  styleTags,
  isSelected,
  canManage,
  onClick,
  onEdit,
  onDuplicate,
  onCopyUrl,
  onArchive,
}: PortfolioCardProps) {
  const artist = Array.isArray(item.artist) ? item.artist[0] : item.artist
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

  const primaryPath = item.healed_path ?? item.storage_path
  const imageUrl = primaryPath
    ? `${supabaseUrl}/storage/v1/object/public/artist-portfolio/${primaryPath}`
    : null

  const resolvedTags = styleTags.filter((t) => item.style_tag_ids.includes(t.id))
  const visibleTags = resolvedTags.slice(0, 2)
  const overflowCount = resolvedTags.length - visibleTags.length

  const dateStr = item.healed_at
    ? new Date(item.healed_at).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
    : new Date(item.created_at).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })

