            loading="lazy"
          />
        ) : (
          <div className="w-full h-full bg-muted flex items-center justify-center">
            <ImageOff className="w-5 h-5 text-muted-foreground" />
          </div>
        )}

        {/* Featured star (top-right) */}
        {item.is_featured && (
          <span
            aria-label="Featured piece"
            role="img"
            className="absolute top-2 right-2"
          >
            <Star className="w-3 h-3 fill-destructive text-destructive" />
          </span>
        )}

        {/* Healed indicator (bottom-left) */}
        {item.healed_path && (
          <span
            aria-label="Healed photograph available"
            role="img"
            className="absolute bottom-2 left-2 rounded-full bg-card border border-border px-2 py-0.5 text-[10px] font-medium text-foreground uppercase tracking-[0.06em]"
          >
