        {canManage && (
          <div className="absolute inset-0 bg-foreground/[0.72] opacity-0 group-hover:opacity-100 transition-opacity duration-150 flex items-center justify-center">
            <div className="grid grid-cols-2 gap-2 p-3">
              {[
                { label: 'Edit', shortcut: 'E', action: onEdit, Icon: Edit2 },
                { label: 'Duplicate', shortcut: 'D', action: onDuplicate, Icon: RotateCcw },
                { label: 'Copy URL', shortcut: 'U', action: onCopyUrl, Icon: Copy },
                { label: 'Archive', shortcut: 'A', action: onArchive, Icon: Archive },
              ].map(({ label, shortcut, action, Icon }) => (
                <button
                  key={label}
                  type="button"
                  aria-label={`${label} portfolio item`}
                  onClick={(e) => {
                    e.stopPropagation()
                    action()
                  }}
                  className="flex items-center gap-1.5 bg-card text-foreground rounded-md px-2.5 py-1.5 text-xs font-medium hover:bg-muted transition-colors min-h-[44px] justify-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <Icon className="w-3 h-3" />
                  {label}
                  <kbd className="text-[10px] text-muted-foreground font-mono ml-0.5">{shortcut}</kbd>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Bottom text area */}
      <button
        type="button"
        className="w-full text-left px-3 pt-2.5 pb-3 focus-visible:outline-none"
        onClick={onClick}
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            onClick()
          }
        }}
      >
        <div className="flex items-baseline gap-0">
          <p className="font-serif text-base font-normal text-foreground leading-snug line-clamp-1">
            {item.caption ?? 'Untitled'}
          </p>
          <span className="text-xs text-muted-foreground ml-2 tabular-nums shrink-0">{dateStr}</span>
        </div>
        {artist && (
          <p className="text-xs text-muted-foreground mt-0.5">{artist.display_name}</p>
