/**
 * Portfolio item detail — progression strip + meta + visibility.
 * Per Vega spec Component 10.
 */
import { Plus, Pin, PinOff, ExternalLink } from 'lucide-react'
import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import type { PortfolioItemWithArtist } from '@/lib/portfolio/queries'
import { Skeleton } from '@/components/ui/skeleton'
import { addProgressionPhoto, pinPortfolioItem } from '@/app/actions/portfolio'

const STAGES = [
  { key: 'reference', label: 'REFERENCE' },
  { key: 'stencil', label: 'STENCIL' },
  { key: 'fresh', label: 'FRESH' },
  { key: 'healed', label: 'HEALED' },
] as const

type Stage = (typeof STAGES)[number]['key']

interface PortfolioDetailProps {
  item: PortfolioItemWithArtist
  styleTags: Array<{ id: string; name: string }>
  onPin?: (isFeatured: boolean) => void
}

export function PortfolioDetail({ item, styleTags, onPin }: PortfolioDetailProps) {
  const artist = Array.isArray(item.artist) ? item.artist[0] : item.artist
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  const resolvedTags = styleTags.filter((t) => item.style_tag_ids.includes(t.id))

  const [isFeatured, setIsFeatured] = useState(item.is_featured)

  function getPhotoUrl(path: string | null): string | null {
    if (!path) return null
    return `${supabaseUrl}/storage/v1/object/public/artist-portfolio/${path}`
  }

  const stagePhotos: Record<Stage, string | null> = {
    reference: getPhotoUrl(item.reference_path),
    stencil: getPhotoUrl(item.stencil_path),
    fresh: getPhotoUrl(item.fresh_path),
    healed: getPhotoUrl(item.healed_path),
  }

  async function handlePhotoUpload(stage: Stage, file: File) {
    const result = await addProgressionPhoto(item.id, stage, file)
    if (!result.success) {
      // Silently log — UI can show toast from parent
    }
  }

  async function handlePinToggle() {
    const newVal = !isFeatured
    setIsFeatured(newVal)
    await pinPortfolioItem(item.id, newVal)
    onPin?.(newVal)
  }

  return (
    <div className="p-6 space-y-6 overflow-y-auto">
      {/* PHOTO PROGRESSION STRIP */}
      <div>
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground mb-3">
          Photo Progression
        </p>
        <div className="flex gap-2">
          {STAGES.map(({ key, label }) => {
            const url = stagePhotos[key]
            return (
              <div key={key} className="flex flex-col items-center gap-1">
                <label
                  className="group/slot relative cursor-pointer"
                  aria-label={`${url ? 'Replace' : 'Add'} ${label.toLowerCase()} photo`}
                >
                  <div
                    className={[
                      'w-[68px] h-[68px] rounded-md overflow-hidden transition-colors',
                      url
                        ? 'border border-border'
                        : 'bg-muted border border-dashed border-border group-hover/slot:border-foreground flex items-center justify-center',
                    ].join(' ')}
                  >
                    {url ? (
                      <img
                        src={url}
                        alt={`${label.toLowerCase()} photo`}
                        className="w-full h-full object-cover"
                        loading="lazy"
                      />
                    ) : (
                      <Plus className="w-3 h-3 text-muted-foreground group-hover/slot:text-foreground" />
                    )}
                  </div>
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    className="sr-only"
                    onChange={(e) => {
                      const file = e.target.files?.[0]
                      if (file) void handlePhotoUpload(key, file)
                    }}
                  />
                </label>
                <p className="text-[10px] font-medium uppercase tracking-[0.06em] text-muted-foreground text-center">
                  {label}
                </p>
              </div>
            )
          })}
        </div>
      </div>

      <hr className="border-border" />

      {/* META TABLE */}
      <div>
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground mb-3">
          Details
        </p>
        <dl className="space-y-2.5">
          {artist && (
            <div className="flex gap-6">
              <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground w-16 shrink-0 pt-0.5">
                Artist
              </dt>
              <dd className="text-sm text-foreground">{artist.display_name}</dd>
            </div>
          )}
          {item.healed_at && (
            <div className="flex gap-6">
              <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground w-16 shrink-0 pt-0.5">
                Healed
              </dt>
              <dd className="text-sm text-foreground tabular-nums">
                {new Date(item.healed_at).toLocaleDateString('en-US', {
                  month: 'short',
                  day: 'numeric',
                  year: 'numeric',
                })}
              </dd>
            </div>
          )}
          {item.linked_project_id && (
            <div className="flex gap-6">
              <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground w-16 shrink-0 pt-0.5">
                Session
              </dt>
              <dd className="text-sm">
                <a
                  href={`/projects/${item.linked_project_id}`}
                  className="text-foreground underline hover:text-muted-foreground transition-colors inline-flex items-center gap-1"
                >
                  View session
                  <ExternalLink className="w-3 h-3" />
                </a>
              </dd>
            </div>
          )}
          {resolvedTags.length > 0 && (
            <div className="flex gap-6">
              <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground w-16 shrink-0 pt-0.5">
                Style
              </dt>
              <dd className="flex flex-wrap gap-1">
                {resolvedTags.map((tag) => (
                  <span
                    key={tag.id}
                    className="rounded-full border border-border/50 bg-muted/40 px-2.5 py-0.5 text-[11px] text-muted-foreground"
                  >
                    {tag.name}
                  </span>
                ))}
              </dd>
            </div>
          )}
        </dl>
      </div>

      <hr className="border-border" />

      {/* VISIBILITY */}
      <div className="space-y-3">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
          Visibility
        </p>
        <div className="flex items-center gap-3">
          <Checkbox
            id="feature-item"
            checked={isFeatured}
            onCheckedChange={() => void handlePinToggle()}
            aria-label="Feature this item on public profile"
          />
          <Label htmlFor="feature-item" className="text-sm text-foreground cursor-pointer">
            Show on public profile
          </Label>
          <Button
            variant="outline"
            size="sm"
            onClick={() => void handlePinToggle()}
            className="ml-auto gap-1.5 min-h-[44px]"
          >
            {isFeatured ? (
              <>
                <PinOff className="w-3.5 h-3.5" />
                Unpin
              </>
            ) : (
              <>
                <Pin className="w-3.5 h-3.5" />
                Pin
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  )
}

