  return (
    <div className="p-6 space-y-6">
      <div className="flex gap-2">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="flex flex-col items-center gap-1">
            <Skeleton className="w-[68px] h-[68px] rounded-md" />
