'use client'

/**
 * Pull-from-session dialog.
 * Per Vega spec Component 15.
 */
import { useState, useEffect } from 'react'
import { Search, Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { pullFromSession, type PullFromSessionResult } from '@/app/actions/portfolio'

interface Candidate {
  id: string
  title: string
  artist_id: string
  artist_name: string
  completed_at: string | null
  photo_count: number
}

interface PullFromSessionDialogProps {
  open: boolean
  onOpenChange: (v: boolean) => void
  artists: Array<{ id: string; display_name: string }>
  onPulled: (result: PullFromSessionResult) => void
}

export function PullFromSessionDialog({
  open,
  onOpenChange,
  artists,
  onPulled,
}: PullFromSessionDialogProps) {
  const [candidates, setCandidates] = useState<Candidate[]>([])
  const [loading, setLoading] = useState(false)
  const [pulling, setPulling] = useState<string | null>(null)
  const [artistFilter, setArtistFilter] = useState('all')
  const [search, setSearch] = useState('')

  useEffect(() => {
    if (!open) return

    setLoading(true)
    fetch('/api/portfolio/pull-candidates')
      .then((r) => r.json())
      .then((data: { candidates: Candidate[] }) => {
        setCandidates(data.candidates ?? [])
      })
      .catch(() => {
        setCandidates([])
      })
      .finally(() => setLoading(false))
  }, [open])

  const filtered = candidates.filter((c) => {
    if (artistFilter !== 'all' && c.artist_id !== artistFilter) return false
    if (search && !c.title.toLowerCase().includes(search.toLowerCase())) return false
    return true
  })

  async function handlePull(candidate: Candidate) {
    setPulling(candidate.id)
    try {
      const result = await pullFromSession(candidate.id)
      if ('error' in result) {
        // Parent can handle toast
        return
      }
      onPulled(result)
      onOpenChange(false)
    } finally {
      setPulling(null)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-lg w-full shadow-overlay"
        aria-labelledby="pull-session-dialog-title"
      >
        <DialogHeader>
          <DialogTitle id="pull-session-dialog-title">
            Pull from completed session
          </DialogTitle>
        </DialogHeader>

        {/* Filters */}
        <div className="flex items-center gap-2">
          <Select value={artistFilter} onValueChange={setArtistFilter}>
            <SelectTrigger className="w-36 h-9 text-sm" aria-label="Filter by artist">
              <SelectValue placeholder="All artists" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All artists</SelectItem>
              {artists.map((a) => (
                <SelectItem key={a.id} value={a.id}>{a.display_name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <div className="relative flex-1">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search sessions…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-9 text-sm"
            />
          </div>
        </div>

        {/* Session list */}
        <div
          role="list"
          className="max-h-72 overflow-y-auto space-y-1"
          aria-label="Completed sessions"
        >
          {loading ? (
            Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-full rounded-md" />
            ))
          ) : filtered.length === 0 ? (
            <div className="text-sm text-muted-foreground text-center py-8">
              {candidates.length === 0
                ? 'No completed sessions found. Finish a session in Projects to pull photos directly.'
                : 'No sessions match these filters.'}
            </div>
          ) : (
            filtered.map((candidate) => (
              <div
                key={candidate.id}
                role="listitem"
                className="flex items-center justify-between px-3 py-2 rounded-md hover:bg-muted/60 transition-colors"
              >
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-foreground truncate">{candidate.title}</p>
                  <p className="text-xs text-muted-foreground">
                    {candidate.artist_name}
                    {candidate.completed_at && (
                      <span className="ml-2 tabular-nums">
                        {new Date(candidate.completed_at).toLocaleDateString('en-US', {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        })}
                      </span>
                    )}
                    <span className="ml-2">{candidate.photo_count} photo{candidate.photo_count !== 1 ? 's' : ''}</span>
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  aria-label={`Pull from session: ${candidate.title}`}
                  onClick={() => void handlePull(candidate)}
                  disabled={pulling === candidate.id}
                  className="ml-3 shrink-0 min-h-[44px]"
                >
                  {pulling === candidate.id ? (
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  ) : (
                    'Pull'
                  )}
                </Button>
              </div>
            ))
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

