  SelectValue,
} from '@/components/ui/select'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'

interface StyleTag { id: string; name: string }
interface Artist { id: string; display_name: string }
interface Sheet { id: string; title: string; slug: string }

interface UploadFormFlashProps {
  artists: Artist[]
  sheets: Sheet[]
  styleTags: StyleTag[]
  aiSuggestions?: {
    title?: string
    description?: string
    placement?: string
    styleTags?: string[]
    oneOfOne?: boolean
  }
  canUseAI: boolean
  onChange: (fields: Record<string, unknown>) => void
}

const PLACEMENT_OPTIONS = ['arm', 'leg', 'back', 'chest', 'hand', 'neck', 'other']
const SESSION_OPTIONS = [
  { value: '1h', label: '1 hour' },
  { value: '2-3h', label: '2–3 hours' },
  { value: 'half-day', label: 'Half day' },
  { value: 'full-day', label: 'Full day' },
]

export function UploadFormFlash({
  artists,
  sheets,
  styleTags,
  aiSuggestions,
  canUseAI,
  onChange,
}: UploadFormFlashProps) {
  const [title, setTitle] = useState(aiSuggestions?.title ?? '')
  const [description, setDescription] = useState(aiSuggestions?.description ?? '')
  const [artistId, setArtistId] = useState(artists[0]?.id ?? '')
  const [sheetId, setSheetId] = useState('')
  const [priceCents, setPriceCents] = useState('')
  const [depositCents, setDepositCents] = useState('')
  const [sessionLength, setSessionLength] = useState('1h')
  const [sizeInches, setSizeInches] = useState('')
  const [placement, setPlacement] = useState(aiSuggestions?.placement ?? '')
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>(
    aiSuggestions?.styleTags
      ? styleTags.filter((t) => aiSuggestions.styleTags?.includes(t.name)).map((t) => t.id)
      : [],
  )
  const [isOneOfOne, setIsOneOfOne] = useState(aiSuggestions?.oneOfOne ?? false)
  const [visibility, setVisibility] = useState<'public' | 'private'>('public')
  const [isFeatured, setIsFeatured] = useState(false)
  const [enableWatermark, setEnableWatermark] = useState(true)

  function update(fields: Record<string, unknown>) {
    onChange(fields)
  }

  function SectionLabel({ label }: { label: string }) {
    return (
      <div className="flex items-center gap-3 mb-4">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground shrink-0">
          {label}
        </p>
        <hr className="border-border/50 flex-1" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* SECTION 1 — IMAGE (watermark toggle) */}
      <div>
        <SectionLabel label="Image" />
        <div className="flex items-start gap-2">
          <Checkbox
            id="enable-watermark"
            name="enableWatermark"
            checked={enableWatermark}
            onCheckedChange={(v) => {
              setEnableWatermark(!!v)
              update({ enableWatermark: !!v })
            }}
          />
          <div>
            <Label htmlFor="enable-watermark" className="text-sm text-foreground cursor-pointer">
              Apply studio watermark (recommended)
            </Label>
            <p className="text-xs text-muted-foreground">Watermarked version shown on public profiles.</p>
          </div>
        </div>
        {canUseAI && aiSuggestions && (
          <p className="text-xs text-muted-foreground mt-2">
            AI suggestions applied.{' '}
            <span className="font-mono text-[9px] bg-muted px-1.5 py-0.5 rounded">AI</span>
          </p>
        )}
      </div>

      {/* SECTION 2 — BASIC */}
      <div>
        <SectionLabel label="Basic" />
        <div className="space-y-3">
          <div>
            <Label htmlFor="title" className="text-sm font-medium">
              Title <span className="text-destructive" aria-hidden>*</span>
            </Label>
            <Input
              id="title"
              name="title"
              value={title}
              onChange={(e) => {
                setTitle(e.target.value)
                update({ title: e.target.value })
              }}
              placeholder="2-4 word title"
              required
              aria-required="true"
              className="mt-1"
            />
          </div>
          <div>
            <Label htmlFor="description" className="text-sm text-muted-foreground">Description</Label>
            <Textarea
              id="description"
              name="description"
              value={description}
              onChange={(e) => {
                setDescription(e.target.value)
                update({ description: e.target.value })
              }}
              rows={2}
              placeholder="Brief editorial description"
              className="mt-1 resize-none"
            />
          </div>
          <div>
            <Label htmlFor="artist" className="text-sm font-medium">
              Artist <span className="text-destructive" aria-hidden>*</span>
            </Label>
            <Select
              name="artistId"
              value={artistId}
              onValueChange={(v) => {
                setArtistId(v)
                update({ artistId: v })
              }}
            >
              <SelectTrigger className="mt-1" aria-required="true">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {artists.map((a) => (
                  <SelectItem key={a.id} value={a.id}>{a.display_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* SECTION 3 — PRICING */}
      <div>
        <SectionLabel label="Pricing" />
        <div className="grid grid-cols-2 gap-3">
          <div>
            <Label htmlFor="price" className="text-sm font-medium">
              Price <span className="text-destructive" aria-hidden>*</span>
            </Label>
            <div className="relative mt-1">
              <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
              <Input
                id="price"
                name="priceCents"
                type="number"
                min="0"
                step="1"
                value={priceCents}
                onChange={(e) => {
                  setPriceCents(e.target.value)
                  update({ priceCents: Math.round(parseFloat(e.target.value || '0') * 100) })
                }}
                placeholder="0"
                className="pl-6 tabular-nums"
                required
                aria-required="true"
              />
            </div>
          </div>
          <div>
            <Label htmlFor="deposit" className="text-sm text-muted-foreground">Deposit</Label>
            <div className="relative mt-1">
              <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
              <Input
                id="deposit"
                name="depositCents"
                type="number"
                min="0"
                step="1"
                value={depositCents}
                onChange={(e) => {
                  setDepositCents(e.target.value)
                  update({ depositCents: Math.round(parseFloat(e.target.value || '0') * 100) })
                }}
                placeholder="0"
                className="pl-6 tabular-nums"
              />
            </div>
          </div>
          <div>
            <Label htmlFor="session" className="text-sm font-medium">
              Session length <span className="text-destructive" aria-hidden>*</span>
            </Label>
            <Select
              name="sessionLength"
              value={sessionLength}
              onValueChange={(v) => {
                setSessionLength(v)
                update({ sessionLength: v })
              }}
            >
              <SelectTrigger className="mt-1" aria-required="true">
                <SelectValue />
