              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="size" className="text-sm text-muted-foreground">Size</Label>
            <Input
              id="size"
              name="sizeInches"
              value={sizeInches}
              onChange={(e) => {
                setSizeInches(e.target.value)
                update({ sizeInches: e.target.value })
              }}
              placeholder="3×4 in"
              className="mt-1"
            />
          </div>
        </div>
      </div>

      {/* SECTION 4 — STYLE */}
      <div>
        <SectionLabel label="Style" />
        <div className="space-y-3">
          <div>
            <Label className="text-sm text-muted-foreground">Placement</Label>
            <Select
              name="placement"
              value={placement}
              onValueChange={(v) => {
                setPlacement(v)
                update({ placement: v })
              }}
            >
              <SelectTrigger className="mt-1">
                <SelectValue placeholder="Select placement" />
              </SelectTrigger>
              <SelectContent>
                {PLACEMENT_OPTIONS.map((p) => (
                  <SelectItem key={p} value={p} className="capitalize">{p}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-sm text-muted-foreground mb-2 block">Style tags</Label>
            <div className="flex flex-wrap gap-2">
              {styleTags.map((tag) => {
                const isAI = aiSuggestions?.styleTags?.includes(tag.name)
                const isSelected = selectedTagIds.includes(tag.id)
                return (
                  <button
                    key={tag.id}
                    type="button"
                    aria-pressed={isSelected}
                    onClick={() => {
                      const next = isSelected
                        ? selectedTagIds.filter((id) => id !== tag.id)
                        : [...selectedTagIds, tag.id]
                      setSelectedTagIds(next)
                      update({ styleTagIds: next })
                    }}
                    className={[
                      'inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      isSelected
                        ? 'bg-foreground text-primary-foreground border-foreground'
                        : 'bg-card text-foreground border-border hover:border-foreground',
                    ].join(' ')}
                  >
                    {tag.name}
                    {isAI && <span className="font-mono text-[9px] opacity-60">AI</span>}
                  </button>
                )
              })}
            </div>
          </div>
        </div>
      </div>

      {/* SECTION 5 — ONE-OF-ONE */}
      <div>
        <SectionLabel label="One-of-one" />
        <div className="flex items-start gap-2">
          <Checkbox
            id="is-one-of-one"
            name="isOneOfOne"
            checked={isOneOfOne}
            onCheckedChange={(v) => {
              setIsOneOfOne(!!v)
              update({ isOneOfOne: !!v })
            }}
          />
          <div>
            <Label htmlFor="is-one-of-one" className="text-sm text-foreground cursor-pointer">
              Mark as one-of-one (unique, unrepeatable design)
            </Label>
            {isOneOfOne && (
              <p className="text-xs text-muted-foreground mt-0.5">
                Sold status will be permanent. No reprints, no duplicates.
              </p>
            )}
          </div>
        </div>
      </div>

      {/* SECTION 6 — SHEET */}
      <div>
        <SectionLabel label="Sheet" />
        <Select
          name="sheetId"
          value={sheetId || 'none'}
          onValueChange={(v) => {
            const val = v === 'none' ? '' : v
            setSheetId(val)
            update({ sheetId: val || null })
          }}
        >
          <SelectTrigger>
            <SelectValue placeholder="None / Standalone" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="none">None / Standalone</SelectItem>
            {sheets.map((s) => (
              <SelectItem key={s.id} value={s.id}>{s.title}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* SECTION 7 — VISIBILITY */}
      <div>
        <SectionLabel label="Visibility" />
        <RadioGroup
          name="visibility"
          value={visibility}
          onValueChange={(v) => {
            setVisibility(v as 'public' | 'private')
            update({ visibility: v })
          }}
          className="space-y-2"
        >
          <div className="flex items-center gap-2">
            <RadioGroupItem value="public" id="visibility-public" />
            <Label htmlFor="visibility-public" className="text-sm cursor-pointer">
              Public — visible on studio profile
            </Label>
          </div>
          <div className="flex items-center gap-2">
            <RadioGroupItem value="private" id="visibility-private" />
            <Label htmlFor="visibility-private" className="text-sm cursor-pointer">
              Private — studio only, not on public profile
            </Label>
          </div>
        </RadioGroup>
        <div className="flex items-center gap-2 mt-3">
          <Checkbox
            id="is-featured"
            name="isFeatured"
            checked={isFeatured}
            onCheckedChange={(v) => {
              setIsFeatured(!!v)
              update({ isFeatured: !!v })
            }}
          />
          <Label htmlFor="is-featured" className="text-sm cursor-pointer">
            Feature this piece
          </Label>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * Portfolio item upload form — 3 sections + progression slots + Pull-from-Session.
 * Per Vega spec Component 14.
 */
import { useState } from 'react'
import { Plus, Link2 } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

interface StyleTag { id: string; name: string }
interface Artist { id: string; display_name: string }

interface UploadFormPortfolioProps {
  artists: Artist[]
  styleTags: StyleTag[]
  onPullFromSession: () => void
  onChange: (fields: Record<string, unknown>) => void
}

type Stage = 'reference' | 'stencil' | 'fresh' | 'healed'
const STAGES: { key: Stage; label: string }[] = [
  { key: 'reference', label: 'Reference' },
  { key: 'stencil', label: 'Stencil' },
  { key: 'fresh', label: 'Fresh' },
  { key: 'healed', label: 'Healed' },
]

export function UploadFormPortfolio({
  artists,
  styleTags,
  onPullFromSession,
  onChange,
}: UploadFormPortfolioProps) {
  const [photos, setPhotos] = useState<Partial<Record<Stage, File>>>({})
  const [artistId, setArtistId] = useState(artists[0]?.id ?? '')
  const [caption, setCaption] = useState('')
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>([])
  const [visibility, setVisibility] = useState<'public' | 'private'>('public')
  const [isFeatured, setIsFeatured] = useState(false)

  function handlePhotoChange(stage: Stage, file: File) {
    const updated = { ...photos, [stage]: file }
    setPhotos(updated)
    onChange({ [`${stage}Photo`]: file })
  }

  function SectionLabel({ label }: { label: string }) {
    return (
      <div className="flex items-center gap-3 mb-4">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground shrink-0">
          {label}
        </p>
        <hr className="border-border/50 flex-1" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* SECTION 1 — PHOTOS */}
      <div>
        <SectionLabel label="Photos" />
        <p className="text-xs text-muted-foreground mb-3">
          At least one photo (Fresh or Healed) required.
        </p>
        <div className="flex gap-3">
          {STAGES.map(({ key, label }) => {
            const file = photos[key]
            const previewUrl = file ? URL.createObjectURL(file) : null

            return (
              <div key={key} className="flex flex-col items-center gap-1">
                <label
                  aria-label={`${previewUrl ? 'Replace' : 'Add'} ${label.toLowerCase()} photo`}
                  className="group/slot relative cursor-pointer block"
                >
                  <div
                    className={[
                      'w-[80px] h-[80px] rounded-md overflow-hidden transition-colors',
                      previewUrl
                        ? 'border border-border'
                        : 'bg-muted border border-dashed border-border group-hover/slot:border-foreground flex items-center justify-center',
                    ].join(' ')}
                  >
                    {previewUrl ? (
                      <img
                        src={previewUrl}
                        alt={`${label} photo preview`}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <Plus className="w-3 h-3 text-muted-foreground group-hover/slot:text-foreground" />
                    )}
                  </div>
                  <input
                    type="file"
                    name={`${key}Photo`}
                    accept="image/jpeg,image/png,image/webp"
                    className="sr-only"
                    onChange={(e) => {
                      const f = e.target.files?.[0]
                      if (f) handlePhotoChange(key, f)
                    }}
                  />
                </label>
                <p className="text-[10px] font-medium text-muted-foreground text-center">{label}</p>
              </div>
            )
          })}
        </div>

        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onPullFromSession}
          className="mt-3 w-full gap-2 min-h-[44px]"
        >
          <Link2 className="w-3.5 h-3.5" />
          Pull from session
        </Button>
      </div>

      {/* SECTION 2 — DETAILS */}
      <div>
        <SectionLabel label="Details" />
        <div className="space-y-3">
          <div>
            <Label htmlFor="caption" className="text-sm text-muted-foreground">Title</Label>
            <Input
              id="caption"
              name="caption"
              value={caption}
              onChange={(e) => {
                setCaption(e.target.value)
                onChange({ caption: e.target.value })
              }}
              placeholder="Optional title or description"
              className="mt-1"
            />
          </div>
          <div>
            <Label htmlFor="portfolio-artist" className="text-sm font-medium">
              Artist <span className="text-destructive" aria-hidden>*</span>
            </Label>
            <Select
              name="artistId"
              value={artistId}
              onValueChange={(v) => {
                setArtistId(v)
                onChange({ artistId: v })
              }}
            >
              <SelectTrigger className="mt-1" id="portfolio-artist" aria-required="true">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {artists.map((a) => (
                  <SelectItem key={a.id} value={a.id}>{a.display_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* SECTION 3 — STYLE & VISIBILITY */}
      <div>
        <SectionLabel label="Style & Visibility" />
        <div className="space-y-4">
          <div>
            <Label className="text-sm text-muted-foreground mb-2 block">Style tags</Label>
            <div className="flex flex-wrap gap-2">
              {styleTags.map((tag) => {
                const isSelected = selectedTagIds.includes(tag.id)
                return (
                  <button
                    key={tag.id}
                    type="button"
                    aria-pressed={isSelected}
                    onClick={() => {
                      const next = isSelected
                        ? selectedTagIds.filter((id) => id !== tag.id)
                        : [...selectedTagIds, tag.id]
                      setSelectedTagIds(next)
                      onChange({ styleTagIds: next })
                    }}
                    className={[
                      'inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      isSelected
                        ? 'bg-foreground text-primary-foreground border-foreground'
                        : 'bg-card text-foreground border-border hover:border-foreground',
                    ].join(' ')}
                  >
                    {tag.name}
                  </button>
                )
              })}
            </div>
          </div>

          <RadioGroup
            name="visibility"
            value={visibility}
            onValueChange={(v) => {
              setVisibility(v as 'public' | 'private')
              onChange({ visibility: v })
            }}
            className="space-y-2"
          >
            <div className="flex items-center gap-2">
              <RadioGroupItem value="public" id="portfolio-visibility-public" />
              <Label htmlFor="portfolio-visibility-public" className="text-sm cursor-pointer">
                Public — visible on studio profile
              </Label>
            </div>
            <div className="flex items-center gap-2">
              <RadioGroupItem value="private" id="portfolio-visibility-private" />
              <Label htmlFor="portfolio-visibility-private" className="text-sm cursor-pointer">
                Private — studio only
              </Label>
            </div>
          </RadioGroup>

          <div className="flex items-center gap-2">
            <Checkbox
              id="portfolio-featured"
              name="isFeatured"
              checked={isFeatured}
              onCheckedChange={(v) => {
                setIsFeatured(!!v)
                onChange({ isFeatured: !!v })
              }}
            />
            <Label htmlFor="portfolio-featured" className="text-sm cursor-pointer">
              Feature this piece
            </Label>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * Upload dialog — drag-drop multi-file + form tabs.
 * Desktop: <Dialog>. Mobile: <Drawer> (bottom sheet behavior).
 * Per Vega spec Component 12.
 */
import { useState, useRef, useCallback } from 'react'
import { UploadCloud, Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Progress } from '@/components/ui/progress'
import { UploadFormFlash } from './UploadFormFlash'
import { UploadFormPortfolio } from './UploadFormPortfolio'
import { PullFromSessionDialog } from './PullFromSessionDialog'
import { createFlashPiece, bulkCreateFlashPieces } from '@/app/actions/flash'
import { createPortfolioItem } from '@/app/actions/portfolio'
import type { FlashAITagResult } from '@/lib/ai/flash-vision'

interface UploadDialogProps {
  open: boolean
  onOpenChange: (v: boolean) => void
  initialMode?: 'flash' | 'portfolio'
  artists: Array<{ id: string; display_name: string }>
  sheets: Array<{ id: string; title: string; slug: string }>
  styleTags: Array<{ id: string; name: string }>
  studioId: string
  canUseAI: boolean
  onSuccess?: (mode: 'flash' | 'portfolio') => void
}

export function UploadDialog({
  open,
  onOpenChange,
  initialMode = 'flash',
  artists,
  sheets,
  styleTags,
  studioId,
  canUseAI,
  onSuccess,
}: UploadDialogProps) {
  const [mode, setMode] = useState<'flash' | 'portfolio'>(initialMode)
  const [tab, setTab] = useState<'single' | 'bulk'>('single')
  const [file, setFile] = useState<File | null>(null)
  const [bulkFiles, setBulkFiles] = useState<File[]>([])
  const [bulkSheetId, setBulkSheetId] = useState<string>('')
  const [dragging, setDragging] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [formFields, setFormFields] = useState<Record<string, unknown>>({})
  const [aiSuggestions, setAiSuggestions] = useState<Partial<FlashAITagResult> | null>(null)
  const [aiLoading, setAiLoading] = useState(false)
  const [pullDialogOpen, setPullDialogOpen] = useState(false)
  const [bulkProgress, setBulkProgress] = useState(0)

  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setDragging(false)
      const dropped = Array.from(e.dataTransfer.files).filter((f) =>
        ['image/jpeg', 'image/png', 'image/webp'].includes(f.type),
      )
      if (tab === 'single') {
        if (dropped[0]) {
          setFile(dropped[0])
          if (canUseAI && mode === 'flash') void triggerAiTag(dropped[0])
        }
      } else {
        setBulkFiles(dropped.slice(0, 50))
      }
    },
    [tab, canUseAI, mode],
  )

  async function triggerAiTag(f: File) {
    setAiLoading(true)
    try {
      const url = URL.createObjectURL(f)
      const res = await fetch('/api/ai/flash-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageUrl: url, studioId }),
      })
      if (res.ok) {
        const data = await res.json() as FlashAITagResult
        setAiSuggestions(data)
        setFormFields((prev) => ({
          ...prev,
          title: data.title || prev.title,
          description: data.description || prev.description,
          placement: data.placement || prev.placement,
          styleTagIds: data.styleTagIds.length > 0 ? data.styleTagIds : prev.styleTagIds,
          isOneOfOne: data.oneOfOneSuggested,
        }))
      }
    } catch {
      // AI tag is best-effort
    } finally {
      setAiLoading(false)
    }
  }

  async function handleSubmit() {
    setError(null)
    setUploading(true)

    try {
      if (tab === 'bulk' && mode === 'flash') {
        const fd = new FormData()
        fd.set('artistId', String(formFields['artistId'] ?? artists[0]?.id ?? ''))
        if (bulkSheetId) fd.set('sheetId', bulkSheetId)
        bulkFiles.forEach((f) => fd.append('files', f))

        let done = 0
        const interval = setInterval(() => {
          done = Math.min(done + 1, bulkFiles.length)
          setBulkProgress((done / bulkFiles.length) * 100)
        }, 300)

        const result = await bulkCreateFlashPieces(fd)
        clearInterval(interval)

        if (!result.success) {
          setError(result.error)
          return
        }

        onSuccess?.(mode)
        onOpenChange(false)
        return
      }

      if (!file) {
        setError('Please select an image')
        return
      }

      if (mode === 'flash') {
        const fd = new FormData()
        fd.set('image', file)
        Object.entries(formFields).forEach(([k, v]) => {
          if (Array.isArray(v)) {
            v.forEach((item) => fd.append(k, String(item)))
          } else if (v !== null && v !== undefined) {
            fd.set(k, String(v))
          }
        })

        const result = await createFlashPiece(fd)
        if (!result.success) {
          setError(result.error)
          return
        }
      } else {
        const fd = new FormData()
        Object.entries(formFields).forEach(([k, v]) => {
          if (v instanceof File) {
            fd.set(k, v)
          } else if (Array.isArray(v)) {
            v.forEach((item) => fd.append(k, String(item)))
          } else if (v !== null && v !== undefined) {
            fd.set(k, String(v))
          }
        })

        const result = await createPortfolioItem(fd)
        if (!result.success) {
          setError(result.error)
          return
        }
      }

      onSuccess?.(mode)
      onOpenChange(false)
    } finally {
      setUploading(false)
    }
  }

  const canSubmit = tab === 'single'
    ? (file !== null)
    : bulkFiles.length > 0

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent
          className="max-w-[680px] w-full max-h-[90vh] overflow-y-auto shadow-overlay"
          aria-labelledby="upload-dialog-title"
        >
          <DialogHeader>
            <DialogTitle id="upload-dialog-title">Upload piece</DialogTitle>
          </DialogHeader>

          {/* Mode selector */}
          <div className="flex gap-1 p-0.5 rounded-full bg-muted border border-border">
            {(['flash', 'portfolio'] as const).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMode(m)}
                className={[
                  'flex-1 rounded-full py-1.5 text-sm font-medium transition-colors capitalize',
                  mode === m ? 'bg-card text-foreground shadow-soft' : 'text-muted-foreground hover:text-foreground',
                ].join(' ')}
              >
                {m}
              </button>
            ))}
          </div>

          {/* Single / Bulk tabs */}
          <Tabs value={tab} onValueChange={(v) => setTab(v as 'single' | 'bulk')}>
            <TabsList className="w-full">
              <TabsTrigger value="single" className="flex-1">Single piece</TabsTrigger>
              {mode === 'flash' && (
                <TabsTrigger value="bulk" className="flex-1">Bulk folder</TabsTrigger>
              )}
            </TabsList>

            <TabsContent value="single" className="space-y-4 mt-4">
              {/* Drop zone */}
              {!file ? (
                <div
                  role="button"
                  tabIndex={0}
                  aria-label="Drop image here or click to browse"
                  onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
                  onDragLeave={() => setDragging(false)}
                  onDrop={handleDrop}
                  onClick={() => fileInputRef.current?.click()}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault()
                      fileInputRef.current?.click()
                    }
                  }}
                  className={[
                    'border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors',
                    dragging ? 'border-foreground bg-muted/60' : 'border-border bg-muted/40 hover:bg-muted/60',
                  ].join(' ')}
                >
                  <UploadCloud className="w-6 h-6 text-muted-foreground mx-auto mb-3" />
                  <p className="text-sm text-muted-foreground">
                    Drag & drop images here
                  </p>
                  <p className="text-xs text-muted-foreground mt-1">
                    or click to browse · PNG, JPG, WEBP — up to 10 MB each
                  </p>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    className="sr-only"
                    onChange={(e) => {
                      const f = e.target.files?.[0]
                      if (f) {
                        setFile(f)
                        if (canUseAI && mode === 'flash') void triggerAiTag(f)
                      }
                    }}
                  />
                </div>
              ) : (
                <div className="flex items-start gap-3">
                  <img
                    src={URL.createObjectURL(file)}
                    alt="Preview"
                    className="w-[120px] h-[120px] rounded-md object-cover shrink-0 border border-border"
                  />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-foreground truncate">{file.name}</p>
                    <p className="text-xs text-muted-foreground">{(file.size / 1024 / 1024).toFixed(1)} MB</p>
                    {aiLoading && (
                      <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                        <Loader2 className="w-3 h-3 animate-spin" />
                        Analyzing image…
                      </p>
                    )}
                    {aiSuggestions && !aiLoading && (
                      <p className="text-xs text-muted-foreground mt-1">
                        <span className="font-mono text-[9px] bg-muted px-1 py-0.5 rounded mr-1">AI</span>
                        Suggestions applied
                      </p>
                    )}
                    <button
                      type="button"
                      onClick={() => { setFile(null); setAiSuggestions(null) }}
                      className="text-xs text-muted-foreground hover:text-foreground mt-1 underline"
                    >
                      Remove
                    </button>
                  </div>
                </div>
              )}

              {/* Form */}
              {file && (
                mode === 'flash' ? (
                  <UploadFormFlash
                    artists={artists}
                    sheets={sheets}
                    styleTags={styleTags}
                    aiSuggestions={aiSuggestions ?? undefined}
                    canUseAI={canUseAI}
                    onChange={(fields) => setFormFields((prev) => ({ ...prev, ...fields }))}
                  />
                ) : (
                  <UploadFormPortfolio
                    artists={artists}
                    styleTags={styleTags}
                    onPullFromSession={() => setPullDialogOpen(true)}
                    onChange={(fields) => setFormFields((prev) => ({ ...prev, ...fields }))}
                  />
                )
              )}
            </TabsContent>

            <TabsContent value="bulk" className="space-y-4 mt-4">
              {/* Bulk drop zone */}
              {bulkFiles.length === 0 ? (
                <div
                  role="button"
                  tabIndex={0}
                  aria-label="Drop images here or click to browse"
                  onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
                  onDragLeave={() => setDragging(false)}
                  onDrop={handleDrop}
                  onClick={() => fileInputRef.current?.click()}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault()
                      fileInputRef.current?.click()
                    }
                  }}
                  className={[
                    'border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors',
                    dragging ? 'border-foreground bg-muted/60' : 'border-border bg-muted/40 hover:bg-muted/60',
                  ].join(' ')}
                >
                  <UploadCloud className="w-6 h-6 text-muted-foreground mx-auto mb-3" />
                  <p className="text-sm text-muted-foreground">
                    Drag a folder of images here
                  </p>
                  <p className="text-xs text-muted-foreground mt-1">Up to 50 files · PNG, JPG, WEBP</p>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    multiple
                    className="sr-only"
                    onChange={(e) => {
                      const files = Array.from(e.target.files ?? []).slice(0, 50)
                      setBulkFiles(files)
                    }}
                  />
                </div>
              ) : (
                <div className="space-y-3">
                  <p className="text-sm text-foreground font-medium">
                    {bulkFiles.length} image{bulkFiles.length !== 1 ? 's' : ''} selected
                  </p>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Assign to sheet (optional)</p>
                    <Select value={bulkSheetId || 'none'} onValueChange={(v) => setBulkSheetId(v === 'none' ? '' : v)}>
                      <SelectTrigger className="w-48">
                        <SelectValue placeholder="No sheet" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">No sheet</SelectItem>
                        {sheets.map((s) => (
                          <SelectItem key={s.id} value={s.id}>{s.title}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  {uploading && (
                    <div className="space-y-1">
                      <Progress value={bulkProgress} className="h-1.5" />
                      <p className="text-xs text-muted-foreground">Uploading {bulkFiles.length} designs…</p>
                    </div>
                  )}
                  <button
                    type="button"
                    onClick={() => setBulkFiles([])}
                    className="text-xs text-muted-foreground hover:text-foreground underline"
                  >
                    Clear selection
                  </button>
                </div>
              )}
            </TabsContent>
          </Tabs>

          {/* Error */}
          {error && (
            <div className="rounded-md bg-destructive/10 border border-destructive/20 px-3 py-2">
              <p className="text-xs text-destructive">{error}</p>
            </div>
          )}

          {/* Footer */}
          <div className="flex items-center justify-between border-t border-border pt-4 mt-2">
            <Button
              type="button"
              variant="ghost"
              onClick={() => onOpenChange(false)}
              className="min-h-[44px]"
            >
              Cancel
            </Button>
            <Button
              type="button"
              onClick={() => void handleSubmit()}
              disabled={!canSubmit || uploading}
              className="min-h-[44px] gap-2"
            >
              {uploading ? (
                <>
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  Uploading…
                </>
              ) : (
                'Upload'
              )}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <PullFromSessionDialog
        open={pullDialogOpen}
        onOpenChange={setPullDialogOpen}
        artists={artists}
        onPulled={() => {
          setPullDialogOpen(false)
        }}
      />
    </>
  )
}

'use client'

/**
 * Wall view — full-bleed grid for iPad/front-desk display.
 * Per Vega spec Component 17.
 * Hidden on mobile (<768px).
 */
import { ChevronLeft } from 'lucide-react'
import { Button } from '@/components/ui/button'
import type { FlashPieceWithRelations } from '@/lib/portfolio/queries'
import { flashPublicUrl } from '@/lib/storage/flash-paths'
import { Skeleton } from '@/components/ui/skeleton'
import { useEffect } from 'react'

interface WallViewProps {
  pieces: FlashPieceWithRelations[]
  canManage: boolean
  onExit: () => void
  onSelect: (id: string) => void
  onUpload?: () => void
}

export function WallView({ pieces, canManage, onExit, onSelect, onUpload }: WallViewProps) {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

  // Escape key exits
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onExit()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [onExit])

  return (
    <div
      role="grid"
      aria-label="Flash wall view"
      className="fixed inset-0 z-50 bg-background overflow-hidden"
    >
      {/* Header */}
      <div className="sticky top-0 z-10 bg-background border-b border-border px-4 py-2 flex items-center justify-between">
        <Button
          variant="ghost"
          size="sm"
          onClick={onExit}
          className="gap-1.5 min-h-[44px]"
          aria-label="Exit wall view"
        >
          <ChevronLeft className="w-4 h-4" />
          Exit wall view
        </Button>
        {canManage && onUpload && (
          <Button onClick={onUpload} size="sm" className="min-h-[44px]">
            + Upload
          </Button>
        )}
      </div>

      {/* Grid */}
      <div
        className="overflow-y-auto h-[calc(100vh-3rem)] grid grid-cols-[repeat(auto-fill,minmax(160px,1fr))] gap-1 p-1 lg:grid-cols-[repeat(auto-fill,minmax(160px,1fr))] md:grid-cols-[repeat(auto-fill,minmax(140px,1fr))]"
      >
        {pieces.length === 0 ? (
          <div className="col-span-full flex items-center justify-center h-64">
            <p className="text-sm text-muted-foreground">No pieces to display.</p>
          </div>
        ) : (
          pieces.map((piece) => {
            const imageUrl = piece.watermarked_path
              ? flashPublicUrl(piece.watermarked_path)
              : piece.storage_path
                ? `${supabaseUrl}/storage/v1/object/public/artist-portfolio/${piece.storage_path}`
                : null
            const artist = Array.isArray(piece.artist) ? piece.artist[0] : piece.artist

            return (
              <div
                key={piece.id}
                role="gridcell"
                aria-label={`${piece.title}${artist ? ` by ${artist.display_name}` : ''}`}
                className="aspect-[3/4] overflow-hidden bg-muted cursor-pointer group"
                onClick={() => onSelect(piece.id)}
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onSelect(piece.id)
                  }
                }}
              >
                {imageUrl ? (
                  <img
                    src={imageUrl}
                    alt={`${piece.title} flash piece`}
                    className={[
                      'w-full h-full object-cover group-hover:opacity-80 transition-opacity duration-150',
                      piece.status === 'sold' ? 'grayscale' : '',
                    ].join(' ')}
                    loading="lazy"
                  />
                ) : (
                  <div className="w-full h-full bg-muted" />
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

export function WallViewSkeleton() {
  return (
    <div className="fixed inset-0 z-50 bg-background overflow-hidden">
      <div className="h-12 border-b border-border bg-background" />
      <div className="grid grid-cols-[repeat(auto-fill,minmax(160px,1fr))] gap-1 p-1">
        {Array.from({ length: 24 }).map((_, i) => (
          <Skeleton key={i} className="aspect-[3/4]" />
        ))}
      </div>
    </div>
  )
}

'use client'

/**
 * Portfolio page top-level client component.
 * Owns URL search param state, filter state, panel open state, bulk progress.
 * Per Vega spec Component 1.
 */
import { useState, useCallback, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { Progress } from '@/components/ui/progress'
import { ModeToggle } from './ModeToggle'
import { SavedViewsRow } from './SavedViewsRow'
import { PortfolioToolbar } from './PortfolioToolbar'
import { FlashCard, FlashCardSkeleton } from './FlashCard'
import { PortfolioCard, PortfolioCardSkeleton } from './PortfolioCard'
import { DetailPanel } from './DetailPanel'
import { EmptyState } from './EmptyState'
import { WallView } from './WallView'
import { UploadDialog } from './UploadDialog'
import { useFlashPiecesRealtime } from '@/hooks/useFlashPiecesRealtime'
import { useBulkUploadProgress } from '@/hooks/useBulkUploadProgress'
import type { FlashPieceWithRelations, PortfolioItemWithArtist } from '@/lib/portfolio/queries'
import {
  type FlashStatus,
  type SortOption,
  type ViewDensity,
  DEFAULT_FILTER_STATE,
  getSavedViewsFromStorage,
  deleteSavedViewFromStorage,
  saveSavedViewToStorage,
} from '@/lib/portfolio/saved-views'
import { archiveFlashPiece } from '@/app/actions/flash'
import { toast } from 'sonner'

interface PortfolioPageClientProps {
  mode: 'flash' | 'portfolio'
  flashPieces: FlashPieceWithRelations[]
  portfolioItems: PortfolioItemWithArtist[]
  artists: Array<{ id: string; display_name: string; avatar_url: string | null }>
  styleTags: Array<{ id: string; name: string }>
  studioId: string
  studioSlug: string
  canManage: boolean
  canUploadAI: boolean
}

export function PortfolioPageClient({
  mode,
  flashPieces: initialFlashPieces,
  portfolioItems,
  artists,
  styleTags,
  studioId,
  studioSlug,
  canManage,
  canUploadAI,
}: PortfolioPageClientProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()

  // Flash pieces (refreshable via Realtime)
  const [flashPieces, setFlashPieces] = useState(initialFlashPieces)

  // Panel state
  const [selectedFlashId, setSelectedFlashId] = useState<string | null>(null)
  const [selectedPortfolioId, setSelectedPortfolioId] = useState<string | null>(null)
  const [panelOpen, setPanelOpen] = useState(false)

  // Upload
  const [uploadOpen, setUploadOpen] = useState(false)
  const [bulkUploadId, setBulkUploadId] = useState<string | null>(null)

  // Wall view
  const [density, setDensity] = useState<ViewDensity>('grid')

  // Saved views
  const [savedViews, setSavedViews] = useState(() => getSavedViewsFromStorage(studioId))
  const [activeViewId, setActiveViewId] = useState<string | null>(null)

  // Filters
  const [search, setSearch] = useState('')
  const [styleTags_, setStyleTags] = useState<string[]>([])
  const [statuses, setStatuses] = useState<FlashStatus[]>([])
  const [placements, setPlacements] = useState<string[]>([])
  const [artistId, setArtistId] = useState<string | null>(null)
  const [sort, setSort] = useState<SortOption>('newest')

  // Bulk progress
  const bulkProgress = useBulkUploadProgress(bulkUploadId)

  // Realtime subscription
  useFlashPiecesRealtime({
    studioId,
    onUpdate: () => {
      // Re-trigger server fetch by navigating (ISR + RSC pattern)
      startTransition(() => {
        router.refresh()
      })
    },
  })

  // Filtered data
  const filtered = mode === 'flash'
    ? flashPieces.filter((p) => {
        if (statuses.length > 0 && !statuses.includes(p.status as FlashStatus)) return false
        if (placements.length > 0 && (!p.placement || !placements.includes(p.placement))) return false
        if (artistId && p.artist_id !== artistId) return false
        if (styleTags_.length > 0 && !styleTags_.some((t) => p.style_tag_ids.includes(t))) return false
        if (search) {
          const q = search.toLowerCase()
          const title = p.title.toLowerCase()
          if (!title.includes(q)) return false
        }
        return true
      })
    : portfolioItems.filter((item) => {
        if (artistId && item.artist_id !== artistId) return false
        if (styleTags_.length > 0 && !styleTags_.some((t) => item.style_tag_ids.includes(t))) return false
        if (search) {
          const q = search.toLowerCase()
          if (!(item.caption ?? '').toLowerCase().includes(q)) return false
        }
        return true
      })

  const selectedFlash = selectedFlashId ? flashPieces.find((p) => p.id === selectedFlashId) : null
  const selectedPortfolio = selectedPortfolioId ? portfolioItems.find((p) => p.id === selectedPortfolioId) : null

  const isEmpty = mode === 'flash' ? flashPieces.length === 0 : portfolioItems.length === 0
  const isFilterEmpty = !isEmpty && filtered.length === 0

  function openPanel(id: string) {
    if (mode === 'flash') {
      setSelectedFlashId(id)
    } else {
      setSelectedPortfolioId(id)
    }
    setPanelOpen(true)
  }

  function clearFilters() {
    setSearch('')
    setStyleTags([])
    setStatuses([])
    setPlacements([])
    setArtistId(null)
    setSort('newest')
    setActiveViewId(null)
  }

  async function handleArchive(id: string) {
    const result = await archiveFlashPiece(id)
    if (result.success) {
      toast.success('Archived')
      setFlashPieces((prev) => prev.filter((p) => p.id !== id))
    } else {
      toast.error(result.error)
    }
  }

  function handleCopyUrl(id: string) {
    const url = `${window.location.origin}/p/${studioSlug}/flash/${id}`
    navigator.clipboard.writeText(url).then(() => toast.success('URL copied')).catch(() => {})
  }

  // Wall mode (flash only)
  if (density === 'wall' && mode === 'flash') {
    return (
      <WallView
        pieces={filtered as FlashPieceWithRelations[]}
        canManage={canManage}
        onExit={() => setDensity('grid')}
        onSelect={openPanel}
        onUpload={canManage ? () => setUploadOpen(true) : undefined}
      />
    )
  }

  return (
    <main
      role="main"
      aria-label="Flash and portfolio inventory"
      className="space-y-4"
      id="portfolio-grid"
    >
      {/* Mode toggle */}
      <ModeToggle currentMode={mode} />

      {/* Saved views */}
      <SavedViewsRow
        activeViewId={activeViewId}
        customViews={savedViews}
        onSelect={setActiveViewId}
        onDelete={(id) => {
          deleteSavedViewFromStorage(studioId, id)
          setSavedViews(getSavedViewsFromStorage(studioId))
        }}
        onNew={() => {
          const label = window.prompt('View name:')
          if (!label) return
          const view = {
            id: `custom-${Date.now()}`,
            label,
            filters: { styleTags: styleTags_, statuses, placements, artistId, sort },
          }
          saveSavedViewToStorage(studioId, view)
          setSavedViews(getSavedViewsFromStorage(studioId))
          setActiveViewId(view.id)
        }}
      />

      {/* Toolbar */}
      <PortfolioToolbar
        mode={mode}
        search={search}
        styleTags={styleTags_}
        statuses={statuses}
        placements={placements}
        artistId={artistId}
        sort={sort}
        density={density}
        artists={artists}
        onSearchChange={setSearch}
        onStyleTagsChange={setStyleTags}
        onStatusesChange={setStatuses}
        onPlacementsChange={setPlacements}
        onArtistChange={setArtistId}
        onSortChange={setSort}
        onDensityChange={setDensity}
        onClearAll={clearFilters}
      />

      {/* Grid */}
      {isEmpty ? (
        <EmptyState
          variant="database"
          onUpload={() => setUploadOpen(true)}
          onPull={() => setUploadOpen(true)}
        />
      ) : isFilterEmpty ? (
        <EmptyState
          variant="filter"
          onClearFilters={clearFilters}
          onEditView={() => {
            // Focus toolbar search
            const el = document.querySelector<HTMLInputElement>('[role="search"] input')
            el?.focus()
          }}
        />
      ) : (
        <div className="grid grid-cols-2 gap-2 sm:gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {mode === 'flash'
            ? (filtered as FlashPieceWithRelations[]).map((piece) => (
                <FlashCard
                  key={piece.id}
                  piece={piece}
                  studioSlug={studioSlug}
                  isSelected={selectedFlashId === piece.id && panelOpen}
                  canManage={canManage}
                  onClick={() => openPanel(piece.id)}
                  onEdit={() => openPanel(piece.id)}
                  onDuplicate={() => toast('Duplicate — coming soon')}
                  onCopyUrl={() => handleCopyUrl(piece.id)}
                  onArchive={() => void handleArchive(piece.id)}
                />
              ))
            : (filtered as PortfolioItemWithArtist[]).map((item) => (
                <PortfolioCard
                  key={item.id}
                  item={item}
                  styleTags={styleTags}
                  isSelected={selectedPortfolioId === item.id && panelOpen}
                  canManage={canManage}
                  onClick={() => openPanel(item.id)}
                  onEdit={() => openPanel(item.id)}
                  onDuplicate={() => toast('Duplicate — coming soon')}
                  onCopyUrl={() => {
                    navigator.clipboard.writeText(`${window.location.origin}/portfolio/${item.id}`)
                      .then(() => toast.success('URL copied'))
                      .catch(() => {})
                  }}
                  onArchive={() => toast('Archive — coming soon')}
                />
              ))}
        </div>
      )}

      {/* Detail panel */}
      <DetailPanel
        open={panelOpen}
        mode={mode}
        flashPiece={selectedFlash}
        portfolioItem={selectedPortfolio}
        styleTags={styleTags}
        studioSlug={studioSlug}
        onClose={() => {
          setPanelOpen(false)
          setSelectedFlashId(null)
          setSelectedPortfolioId(null)
        }}
      />

      {/* Upload dialog */}
      <UploadDialog
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        initialMode={mode}
        artists={artists}
        sheets={[]}
        styleTags={styleTags}
        studioId={studioId}
        canUseAI={canUploadAI}
        onSuccess={() => {
          startTransition(() => router.refresh())
          toast.success('Uploaded successfully')
        }}
      />

      {/* Bulk progress bar */}
      {bulkProgress.status === 'running' && (
        <div
          role="status"
          aria-live="polite"
          aria-label={`Bulk upload progress: ${bulkProgress.completed} of ${bulkProgress.total}`}
          className="fixed bottom-0 inset-x-0 z-50 bg-card border-t border-border px-6 py-3 flex items-center justify-between shadow-soft-md animate-in slide-in-from-bottom-2 fade-in-0 duration-200"
        >
          <p className="text-sm text-muted-foreground">
            Tagging {bulkProgress.total} designs. About {Math.ceil((bulkProgress.total - bulkProgress.completed) * 1.3)} seconds.
          </p>
          <div className="flex items-center gap-3">
            <Progress
              value={bulkProgress.total > 0 ? (bulkProgress.completed / bulkProgress.total) * 100 : 0}
              className="w-32 h-1.5"
            />
            <span className="text-xs text-muted-foreground tabular-nums">
              {bulkProgress.completed}/{bulkProgress.total}
            </span>
          </div>
        </div>
      )}

      {bulkProgress.status === 'completed' && (
        <div
          role="status"
          aria-live="polite"
          className="fixed bottom-0 inset-x-0 z-50 bg-card border-t border-border px-6 py-3 flex items-center justify-between shadow-soft-md animate-in slide-in-from-bottom-2 fade-in-0 duration-200"
        >
          <p className="text-sm text-muted-foreground">
            All {bulkProgress.succeededPieceIds.length} designs tagged and saved to Drafts.
          </p>
        </div>
      )}
    </main>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PortfolioPageClient } from '@/components/portfolio/PortfolioPageClient'
import { listFlashPieces, listPortfolioItems } from '@/lib/portfolio/queries'
import { Skeleton } from '@/components/ui/skeleton'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'
import { checkFeatureRpc } from '@/lib/billing/feature-gate'

export const metadata: Metadata = {
  title: 'Flash & Portfolio — InkOS',
}

interface PortfolioPageProps {
  searchParams: Promise<{ mode?: string }>
}

async function PortfolioContent({
  studioId,
  studioSlug,
  canManage,
  canUploadAI,
  mode,
}: {
  studioId: string
  studioSlug: string
  canManage: boolean
  canUploadAI: boolean
  mode: 'flash' | 'portfolio'
}) {
  const supabase = await createClient()

  const [flashPieces, portfolioItems, artists, styleTags] = await Promise.all([
    mode === 'flash' || true  // always fetch both for mode toggle
      ? listFlashPieces(supabase, { studioId, limit: 100 }).catch(() => [])
      : Promise.resolve([]),
    listPortfolioItems(supabase, studioId, { limit: 100 }).catch(() => []),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .order('display_name', { ascending: true })
      .then(({ data }) => data ?? []),
    supabase
      .from('style_tags')
      .select('id, name')
      .eq('studio_id', studioId)
      .order('name', { ascending: true })
      .then(({ data }) => data ?? []),
  ])

  return (
    <PortfolioPageClient
      mode={mode}
      flashPieces={flashPieces}
      portfolioItems={portfolioItems}
      artists={artists}
      styleTags={styleTags}
      studioId={studioId}
      studioSlug={studioSlug}
      canManage={canManage}
      canUploadAI={canUploadAI}
    />
  )
}

