export default async function PortfolioPage({ searchParams }: PortfolioPageProps) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams
  const mode: 'flash' | 'portfolio' = params.mode === 'portfolio' ? 'portfolio' : 'flash'

  const canManage = ['owner', 'admin'].includes(auth.role)
  const supabase = await createClient()
  const canUploadAI = await checkFeatureRpc(supabase, auth.studioId, 'ai_design')

  // Get studio slug
  const { data: studio } = await supabase
    .from('studios')
    .select('slug')
    .eq('id', auth.studioId)
    .maybeSingle()

  const studioSlug = studio?.slug ?? auth.studioId

  return (
    <PageShell>
      <PageHeader
        title="Flash & Portfolio"
        description="Flash inventory, completed work, and public artist profiles."
        actions={
          canManage ? (
            <Button size="sm" asChild>
              <a href="/portfolio?upload=1">+ Upload</a>
            </Button>
          ) : undefined
        }
      />
      <Suspense fallback={<PortfolioSkeleton />}>
        <PortfolioContent
          studioId={auth.studioId}
          studioSlug={studioSlug}
          canManage={canManage}
          canUploadAI={canUploadAI}
          mode={mode}
        />
      </Suspense>
    </PageShell>
  )
}

