import { flashPublicUrl } from '@/lib/storage/flash-paths'

export type CardVariant = 'flash' | 'portfolio'

interface FeaturedCardFlash {
  variant: 'flash'
  id: string
  title: string
  watermarked_path: string | null
  price_cents: number
  currency: string
  status: string
