  artist: { id: string; display_name: string; slug: string | null } | null
  studioSlug: string
  priority?: boolean
}

type FeaturedCardProps = FeaturedCardFlash | FeaturedCardPortfolio

export function FeaturedCard(props: FeaturedCardProps) {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''

  if (props.variant === 'flash') {
    const imageUrl = props.watermarked_path
      ? flashPublicUrl(props.watermarked_path)
      : null

    const price = (props.price_cents / 100).toLocaleString('en-US', {
      style: 'currency',
      currency: props.currency ?? 'USD',
      minimumFractionDigits: 0,
    })

    const isSold = props.status === 'sold'
    const isReserved = props.status === 'reserved'

    return (
      <a
        href={`/p/${props.studioSlug}/flash/${props.id}`}
        className="group relative block aspect-[3/4] rounded-lg overflow-hidden border border-[var(--color-border)] bg-[var(--color-chip-bg)] shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-card-hover)] transition-shadow duration-150 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
        aria-label={`${props.title}${props.artist ? ` by ${props.artist.display_name}` : ''}`}
      >
        {/* Image */}
        {imageUrl && (
          <img
            src={imageUrl}
            alt={`${props.title}${props.artist ? ` by ${props.artist.display_name}` : ''}`}
            className={[
              'w-full h-full object-cover',
              isSold ? 'grayscale' : '',
            ].join(' ')}
            loading={props.priority ? 'eager' : 'lazy'}
            {...(props.priority ? { fetchpriority: 'high' } : {})}
          />
        )}

        {/* Status badge (top-left) */}
        {!isSold && (
          <span
            className={[
              'absolute top-2 left-2 text-[10px] font-bold uppercase tracking-[0.08em] px-1.5 py-0.5 rounded-sm',
              isReserved
                ? 'bg-[var(--color-onyx)]/70 text-[var(--color-bone)]'
                : 'bg-[var(--color-bone)]/90 text-[var(--color-onyx)] border border-[var(--color-border)]',
            ].join(' ')}
          >
            {isReserved ? 'Reserved' : 'Available'}
          </span>
        )}
        {isSold && (
          <span className="absolute top-2 left-2 text-[10px] font-bold uppercase tracking-[0.08em] px-1.5 py-0.5 rounded-sm bg-[var(--color-onyx)] text-[var(--color-bone)]">
            Sold
          </span>
        )}

        {/* 1/1 badge (top-right) */}
        {props.is_one_of_one && (
          <span className="absolute top-2 right-2 text-[10px] font-bold uppercase tracking-[0.08em] bg-[var(--color-bone)]/90 text-[var(--color-onyx)] border border-[var(--color-border)] px-1.5 py-0.5 rounded-sm">
            1/1
          </span>
        )}

        {/* Bottom overlay */}
        <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-[var(--color-onyx)]/60 to-transparent px-3 pb-2.5 pt-6">
          <p className="font-variant-numeric tabular-nums text-[14px] font-bold text-[var(--color-bone)]">
            {price}
          </p>
          {props.artist && (
            <p className="text-[11px] font-normal text-[var(--color-bone)]/80">
              {props.artist.display_name}
            </p>
          )}
        </div>
      </a>
    )
  }

  // Portfolio variant
  const imageUrl = props.storage_path
    ? `${supabaseUrl}/storage/v1/object/public/artist-portfolio/${props.storage_path}`
    : null

  const href = props.artist?.slug
    ? `/p/${props.studioSlug}/${props.artist.slug}`
    : `/p/${props.studioSlug}`

  return (
    <a
      href={href}
      className="group relative block aspect-[3/4] rounded-lg overflow-hidden border border-[var(--color-border)] bg-[var(--color-chip-bg)] shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-card-hover)] transition-shadow duration-150 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
      aria-label={`${props.caption ?? 'Portfolio photo'}${props.artist ? ` by ${props.artist.display_name}` : ''}`}
    >
      {imageUrl && (
        <img
          src={imageUrl}
          alt={props.caption ?? 'Portfolio photo'}
          className="w-full h-full object-cover"
          loading={props.priority ? 'eager' : 'lazy'}
          {...(props.priority ? { fetchpriority: 'high' } : {})}
        />
      )}

      {/* Bottom overlay */}
      {props.artist && (
        <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-[var(--color-onyx)]/60 to-transparent px-3 pb-2.5 pt-6">
          <p className="text-[11px] font-normal text-[var(--color-bone)]/80">
            {props.artist.display_name}
          </p>
        </div>
      )}
    </a>
  )
}

