/**
 * Reserve button — 4-state state machine.
 * Per Pixel spec Global — Reserve Button States.
 */
import { useState } from 'react'
import { Loader2 } from 'lucide-react'

interface ReserveButtonProps {
  pieceId: string
  pieceStatus: string
  isReservedReturn?: boolean
  studioSlug: string
}

export function ReserveButton({
  pieceId,
  pieceStatus,
  isReservedReturn,
  studioSlug,
}: ReserveButtonProps) {
  const [showModal, setShowModal] = useState(false)

  if (isReservedReturn) {
    return (
      <div aria-live="polite" className="space-y-2">
        <p className="font-serif italic text-base text-foreground">
          Reserved. We&apos;ll email you to lock the chair.
        </p>
        <a
          href={`/p/${studioSlug}`}
          className="text-sm text-muted-foreground underline hover:text-foreground transition-colors"
        >
          View all flash →
        </a>
      </div>
    )
  }

  if (pieceStatus !== 'available') {
    const label = pieceStatus === 'reserved' ? 'Reserved' : 'Sold'
    return (
      <button
        type="button"
        disabled
        aria-disabled="true"
        className="w-full bg-[var(--color-stone)]/20 text-[var(--color-stone)] font-semibold text-sm px-5 py-2.5 rounded-md cursor-not-allowed min-h-[44px]"
      >
        {label}
      </button>
    )
  }

  if (showModal) {
    return (
      <ReserveFormInline
        pieceId={pieceId}
        studioSlug={studioSlug}
        onCancel={() => setShowModal(false)}
      />
    )
  }

  return (
    <button
      type="button"
      onClick={() => setShowModal(true)}
      className="w-full bg-[var(--color-onyx)] text-[var(--color-bone)] font-semibold text-sm px-5 py-2.5 rounded-md hover:opacity-90 transition-opacity min-h-[44px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-2"
    >
      Reserve
    </button>
  )
}

function ReserveFormInline({
  pieceId,
  studioSlug,
  onCancel,
}: {
  pieceId: string
  studioSlug: string
  onCancel: () => void
}) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [notes, setNotes] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      // PostHog identify at PII entry point
      if (typeof window !== 'undefined' && 'posthog' in window) {
        const ph = (window as Record<string, unknown>)['posthog'] as { identify?: (id: string, props: Record<string, string>) => void }
        ph.identify?.(email, { email, name })
      }

      const res = await fetch(`/api/flash/${pieceId}/reserve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ clientEmail: email, clientName: name }),
      })

      const data = await res.json() as { checkoutUrl?: string; error?: string }

      if (!res.ok || !data.checkoutUrl) {
        setError(data.error ?? 'Something went wrong. Please try again.')
        return
      }

      window.location.href = data.checkoutUrl
    } catch {
      setError('Something went wrong. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <form onSubmit={(e) => void handleSubmit(e)} className="space-y-3">
      <div>
        <label htmlFor="reserve-name" className="block text-xs font-medium text-muted-foreground mb-1">
          Your name
        </label>
        <input
          id="reserve-name"
          type="text"
          required
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="w-full border border-[var(--color-border)] rounded-md px-3 py-2 text-sm text-foreground bg-[var(--color-background)] focus:outline-none focus:ring-2 focus:ring-[var(--color-ring)] min-h-[44px]"
          placeholder="Your full name"
        />
      </div>
      <div>
        <label htmlFor="reserve-email" className="block text-xs font-medium text-muted-foreground mb-1">
          Email address
        </label>
        <input
          id="reserve-email"
          type="email"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full border border-[var(--color-border)] rounded-md px-3 py-2 text-sm text-foreground bg-[var(--color-background)] focus:outline-none focus:ring-2 focus:ring-[var(--color-ring)] min-h-[44px]"
          placeholder="you@example.com"
        />
      </div>
      <div>
        <label htmlFor="reserve-notes" className="block text-xs font-medium text-muted-foreground mb-1">
          Any notes for the artist
        </label>
        <textarea
          id="reserve-notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          maxLength={500}
          rows={2}
          className="w-full border border-[var(--color-border)] rounded-md px-3 py-2 text-sm text-foreground bg-[var(--color-background)] focus:outline-none focus:ring-2 focus:ring-[var(--color-ring)] resize-none"
          placeholder="Optional"
        />
      </div>

      {error && (
        <p className="text-xs text-[var(--color-destructive)]">{error}</p>
      )}

      <div className="flex gap-2">
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 border border-[var(--color-border)] text-foreground font-medium text-sm px-4 py-2.5 rounded-md hover:bg-muted/60 transition-colors min-h-[44px]"
        >
          Back
        </button>
        <button
          type="submit"
          disabled={loading || !name || !email}
          aria-disabled={loading || !name || !email}
          className="flex-1 bg-[var(--color-onyx)] text-[var(--color-bone)] font-semibold text-sm px-4 py-2.5 rounded-md hover:opacity-90 disabled:opacity-70 disabled:cursor-not-allowed transition-opacity inline-flex items-center justify-center gap-2 min-h-[44px]"
        >
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Reserving…
            </>
          ) : (
            'Continue to payment'
          )}
        </button>
      </div>
    </form>
  )
}

'use client'

/**
 * Artist profile tab bar — Flash ↔ Portfolio tabs with URL hash sync.
 * Per Pixel spec Route 2 tab-bar section.
 */
import { useState, useEffect } from 'react'

interface ArtistProfileTabsProps {
  flashCount: number
  portfolioCount: number
  defaultTab?: 'flash' | 'portfolio'
  onTabChange: (tab: 'flash' | 'portfolio') => void
}

export function ArtistProfileTabs({
  flashCount,
  portfolioCount,
  defaultTab = 'flash',
  onTabChange,
}: ArtistProfileTabsProps) {
  const [activeTab, setActiveTab] = useState<'flash' | 'portfolio'>(() => {
    if (typeof window !== 'undefined') {
      const hash = window.location.hash.replace('#', '')
      if (hash === 'portfolio') return 'portfolio'
      if (hash === 'flash') return 'flash'
    }
    return defaultTab
  })

  useEffect(() => {
    const tab = activeTab
    if (typeof window !== 'undefined') {
      const url = new URL(window.location.href)
      url.hash = tab
      window.history.replaceState(null, '', url.toString())
    }
    onTabChange(tab)
  }, [activeTab, onTabChange])

  return (
    <div className="sticky top-14 z-30 bg-[var(--color-background)] border-b border-[var(--color-border)]">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 flex gap-6 h-11 items-end">
        {(['flash', 'portfolio'] as const).map((tab) => {
          const count = tab === 'flash' ? flashCount : portfolioCount
          const isActive = activeTab === tab

          return (
            <button
              key={tab}
              type="button"
              role="tab"
              aria-selected={isActive}
              onClick={() => setActiveTab(tab)}
              className={[
                'pb-2.5 flex items-center gap-1.5 text-sm font-medium transition-colors border-b-2 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]',
                isActive
                  ? 'border-[var(--color-onyx)] text-[var(--color-onyx)] font-semibold'
                  : 'border-transparent text-[var(--color-stone)] hover:text-[var(--color-onyx)]',
              ].join(' ')}
            >
              {tab === 'flash' ? 'Flash' : 'Portfolio'}
              <span className="text-[11px] tabular-nums text-[var(--color-stone)] ml-0.5">
                {count}
