                    id={item.id}
                    storage_path={item.storage_path}
                    healed_path={item.healed_path}
                    caption={item.caption}
                    style_tag_ids={item.style_tag_ids}
                    styleTags={styleTags}
                    artistSlug={artistSlug}
                    studioSlug={studioSlug}
                  />
                ))}
              </div>
            )}
          </div>
        </section>
      )}
    </>
  )
}

/**
 * /p/[studioSlug]/flash/[pieceId] — Single flash piece detail + Reserve CTA.
 * Per Pixel spec Route 3.
 */
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { ReserveButton } from '@/components/public/ReserveButton'
import { FeaturedCard } from '@/components/public/FeaturedCard'
import { flashPublicUrl } from '@/lib/storage/flash-paths'
import { formatSessionLength } from '@/lib/public/formatSessionLength'

export const revalidate = 30

interface PageProps {
  params: Promise<{ studioSlug: string; pieceId: string }>
  searchParams: Promise<{ reserved?: string }>
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { studioSlug, pieceId } = await params
  const supabase = await createClient()

  const { data: studio } = await supabase.from('studios').select('name, city').eq('slug', studioSlug).maybeSingle()
  const { data: piece } = await supabase
    .from('flash_pieces')
    .select('title, price_cents, currency, session_length, watermarked_path, artist:artists(display_name)')
    .eq('id', pieceId)
    .maybeSingle()

  if (!studio || !piece) return { title: 'Not Found' }
  const artist = Array.isArray(piece.artist) ? piece.artist[0] : piece.artist

  const price = (piece.price_cents / 100).toLocaleString('en-US', {
    style: 'currency',
    currency: piece.currency ?? 'USD',
    minimumFractionDigits: 0,
  })

  return {
    title: `${piece.title}${artist ? ` by ${(artist as { display_name: string }).display_name}` : ''} — ${studio.name}`,
    description: `${piece.title} — ${formatSessionLength(piece.session_length)} session, ${price}. Book with ${artist ? (artist as { display_name: string }).display_name : 'the studio'} at ${studio.name}.`,
    openGraph: {
      images: piece.watermarked_path ? [flashPublicUrl(piece.watermarked_path)] : [],
    },
  }
}

export default async function FlashPieceDetailPage({ params, searchParams }: PageProps) {
  const { studioSlug, pieceId } = await params
  const sp = await searchParams
  const isReservedReturn = sp.reserved === '1'

  const supabase = await createClient()

  const { data: studio } = await supabase
    .from('studios')
    .select('id, name, slug, city')
    .eq('slug', studioSlug)
    .maybeSingle()

  if (!studio) notFound()

  const { data: piece } = await supabase
    .from('flash_pieces')
    .select(`
      id, title, description, watermarked_path, price_cents, deposit_cents,
      currency, status, is_one_of_one, session_length, size_inches, placement,
      style_tag_ids, view_count,
      artist:artists(id, display_name, slug, avatar_url),
      sheet:flash_sheets(id, title, slug)
    `)
    .eq('id', pieceId)
    .eq('visibility', 'public')
    .in('status', ['available', 'reserved', 'sold'])
    .eq('studio_id', studio.id)
    .maybeSingle()

  if (!piece) notFound()

  const artist = Array.isArray(piece.artist) ? piece.artist[0] : piece.artist
  const sheet = Array.isArray(piece.sheet) ? piece.sheet[0] : piece.sheet

  const [styleTags, moreByArtist] = await Promise.all([
    supabase
      .from('style_tags')
      .select('id, name')
      .in('id', piece.style_tag_ids)
      .then(({ data }) => data ?? []),
    artist
      ? supabase
          .from('flash_pieces')
          .select('id, title, watermarked_path, price_cents, currency, status')
          .eq('artist_id', (artist as { id: string }).id)
          .neq('id', pieceId)
          .eq('visibility', 'public')
          .in('status', ['available', 'reserved'])
          .order('created_at', { ascending: false })
          .limit(6)
          .then(({ data }) => data ?? [])
      : Promise.resolve([]),
  ])

  const imageUrl = piece.watermarked_path ? flashPublicUrl(piece.watermarked_path) : null
  const isSold = piece.status === 'sold'

  const price = (piece.price_cents / 100).toLocaleString('en-US', {
    style: 'currency',
    currency: piece.currency ?? 'USD',
    minimumFractionDigits: 0,
  })

  const deposit = piece.deposit_cents > 0
    ? (piece.deposit_cents / 100).toLocaleString('en-US', {
        style: 'currency',
        currency: piece.currency ?? 'USD',
        minimumFractionDigits: 0,
      })
    : null

  const artistData = artist as { id: string; display_name: string; slug: string | null } | null
  const sheetData = sheet as { id: string; title: string; slug: string } | null

  return (
    <>
      {/* Back nav */}
      <div className="max-w-4xl mx-auto px-4 sm:px-6 pt-4">
        <a
          href={artistData?.slug ? `/p/${studioSlug}/${artistData.slug}#flash` : `/p/${studioSlug}`}
          className="text-[12px] text-[var(--color-stone)] hover:text-[var(--color-onyx)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
        >
          ← {artistData?.display_name ?? studio.name}
        </a>
      </div>

      {/* Piece detail */}
      <section aria-label="Flash piece detail">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 py-6 sm:py-10 flex flex-col sm:grid sm:grid-cols-[1fr_280px] lg:grid-cols-[1fr_320px] gap-6 sm:gap-8 lg:gap-12 items-start">
          {/* Left: image */}
          <div className="sm:sticky sm:top-[calc(3.5rem+1px)]">
            <div className="relative aspect-[3/4] w-full overflow-hidden rounded-lg border border-[var(--color-border)] bg-[var(--color-chip-bg)] shadow-[var(--shadow-card)]">
              {imageUrl ? (
                <img
                  src={imageUrl}
                  alt={`${piece.title}${artistData ? ` by ${artistData.display_name}` : ''}`}
                  className={['w-full h-full object-cover', isSold ? 'grayscale' : ''].join(' ')}
                  loading="eager"
                  // @ts-expect-error -- fetchpriority is valid HTML
                  fetchpriority="high"
                />
              ) : (
                <div className="w-full h-full bg-[var(--color-chip-bg)]" />
              )}

              {/* Badges */}
              <span
                className={[
                  'absolute top-2 left-2 text-[10px] font-bold uppercase tracking-[0.08em] px-2 py-1 rounded-sm',
                  piece.status === 'available'
                    ? 'bg-[var(--color-bone)]/90 text-[var(--color-onyx)] border border-[var(--color-border)]'
                    : piece.status === 'reserved'
                      ? 'bg-[var(--color-onyx)]/70 text-[var(--color-bone)]'
                      : 'bg-[var(--color-onyx)] text-[var(--color-bone)]',
                ].join(' ')}
              >
                {piece.status === 'available' ? 'Available' : piece.status === 'reserved' ? 'Reserved' : 'Sold'}
              </span>

              {piece.is_one_of_one && (
                <span className="absolute top-2 right-2 text-[10px] font-bold uppercase tracking-[0.08em] bg-[var(--color-bone)]/90 text-[var(--color-onyx)] border border-[var(--color-border)] px-2 py-1 rounded-sm">
                  1 of 1
                </span>
              )}
            </div>
          </div>

          {/* Right: reserve panel */}
          <div className="flex flex-col gap-5">
            <div>
              <h1 className="font-serif text-[1.75rem] leading-[2rem] font-normal text-[var(--color-onyx)]">
                {piece.title}
              </h1>
              {artistData && (
                <a
                  href={`/p/${studioSlug}/${artistData.slug ?? artistData.id}`}
                  className="text-[13px] text-[var(--color-stone)] hover:text-[var(--color-onyx)] transition-colors mt-0.5 inline-block"
                >
                  by {artistData.display_name}
                </a>
              )}
            </div>

            <p className="font-variant-numeric tabular-nums text-[2.25rem] leading-[2.5rem] font-extrabold text-[var(--color-onyx)]">
              {price}
            </p>

            {deposit && (
              <p className="text-[12px] text-[var(--color-stone)] -mt-3">
                {deposit} deposit to reserve
              </p>
            )}

            <hr className="border-[var(--color-border)]" />

            {/* Meta table */}
            <dl className="grid grid-cols-[auto_1fr] gap-x-6 gap-y-2">
              <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] pt-0.5">Session</dt>
              <dd className="text-[13px] text-[var(--color-onyx)]">{formatSessionLength(piece.session_length)}</dd>

              {piece.size_inches && (
                <>
                  <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] pt-0.5">Size</dt>
                  <dd className="text-[13px] text-[var(--color-onyx)]">{piece.size_inches} inches</dd>
                </>
              )}
              {piece.placement && (
                <>
                  <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] pt-0.5">Placement</dt>
                  <dd className="text-[13px] text-[var(--color-onyx)] capitalize">{piece.placement}</dd>
                </>
              )}
              {sheetData && (
                <>
                  <dt className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] pt-0.5">Sheet</dt>
                  <dd>
                    <a
                      href={`/p/${studioSlug}/sheet/${sheetData.slug}`}
                      className="text-[13px] text-[var(--color-onyx)] underline hover:text-[var(--color-stone)] transition-colors"
                    >
                      {sheetData.title}
                    </a>
                  </dd>
                </>
              )}
            </dl>

            {/* Style tags */}
            {styleTags.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {styleTags.map((tag) => (
                  <span
                    key={tag.id}
                    className="text-[11px] font-medium text-[var(--color-chip-foreground)] bg-[var(--color-chip-bg)] border border-[var(--color-chip-border)] rounded-full px-2.5 py-0.5"
                  >
                    {tag.name}
                  </span>
                ))}
              </div>
            )}

            {/* Description */}
            {piece.description && (
              <p className="text-[13px] text-[var(--color-stone)] leading-relaxed">
                {piece.description}
              </p>
            )}

            <hr className="border-[var(--color-border)]" />

            {/* Reserve button */}
            <ReserveButton
              pieceId={pieceId}
              pieceStatus={piece.status}
              isReservedReturn={isReservedReturn}
              studioSlug={studioSlug}
            />
          </div>
        </div>
      </section>

      {/* More by artist */}
      {moreByArtist.length > 0 && (
        <section aria-label={`More by ${artistData?.display_name ?? 'this artist'}`} className="border-t border-[var(--color-border)]">
          <div className="max-w-4xl mx-auto px-4 sm:px-6 py-6 sm:py-8">
            <p className="text-[11px] font-bold text-[var(--color-stone)] tracking-[0.08em] uppercase mb-4">
              More by {artistData?.display_name?.toUpperCase() ?? 'THIS ARTIST'}
            </p>
            <div className="flex gap-3 overflow-x-auto pb-1 -mx-4 px-4 sm:mx-0 sm:px-0">
              {moreByArtist.map((mp) => (
                <a
                  key={mp.id}
                  href={`/p/${studioSlug}/flash/${mp.id}`}
                  className="shrink-0 w-32 aspect-[3/4] rounded-md overflow-hidden border border-[var(--color-border)] bg-[var(--color-chip-bg)] relative group hover:shadow-[var(--shadow-card-hover)] transition-shadow focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
                >
                  {mp.watermarked_path && (
                    <img
                      src={flashPublicUrl(mp.watermarked_path)}
                      alt={mp.title}
                      className={['w-full h-full object-cover', mp.status === 'sold' ? 'grayscale' : ''].join(' ')}
                      loading="lazy"
                    />
                  )}
                  <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-[var(--color-onyx)]/60 to-transparent px-2 pb-2 pt-4">
                    <p className="tabular-nums text-[12px] font-bold text-[var(--color-bone)]">
                      {(mp.price_cents / 100).toLocaleString('en-US', { style: 'currency', currency: mp.currency ?? 'USD', minimumFractionDigits: 0 })}
                    </p>
                  </div>
                </a>
              ))}
            </div>
          </div>
        </section>
      )}
    </>
  )
}

/**
 * /p/[studioSlug]/sheet/[sheetSlug] — Sheet (drop) detail page.
 * Per Pixel spec Route 4.
 */
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { FeaturedCard } from '@/components/public/FeaturedCard'

export const revalidate = 60

interface PageProps {
  params: Promise<{ studioSlug: string; sheetSlug: string }>
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { studioSlug, sheetSlug } = await params
  const supabase = await createClient()

  const { data: studio } = await supabase.from('studios').select('name, city').eq('slug', studioSlug).maybeSingle()
  const { data: sheet } = await supabase
    .from('flash_sheets')
    .select('title, description')
    .eq('slug', sheetSlug)
    .eq('status', 'active')
    .maybeSingle()

  if (!studio || !sheet) return { title: 'Not Found' }

  return {
    title: `${sheet.title} — ${studio.name}`,
    description: `Explore ${sheet.title} — flash inventory from ${studio.name}${studio.city ? ` in ${studio.city}` : ''}. Browse and reserve.`,
  }
}

export default async function SheetDetailPage({ params }: PageProps) {
  const { studioSlug, sheetSlug } = await params
  const supabase = await createClient()

  const { data: studio } = await supabase
    .from('studios')
    .select('id, name, slug, city')
    .eq('slug', studioSlug)
    .maybeSingle()

  if (!studio) notFound()

  const { data: sheet } = await supabase
    .from('flash_sheets')
    .select('id, title, slug, description, cover_image_url, drop_date')
    .eq('studio_id', studio.id)
    .eq('slug', sheetSlug)
    .eq('status', 'active')
    .maybeSingle()

  if (!sheet) notFound()

  const { data: pieces } = await supabase
    .from('flash_pieces')
    .select('id, title, watermarked_path, price_cents, currency, status, is_one_of_one, artist:artists(id, display_name, slug)')
    .eq('sheet_id', sheet.id)
    .eq('visibility', 'public')
    .in('status', ['available', 'reserved', 'sold'])
    .order('created_at', { ascending: true })

  const pieceList = pieces ?? []

  const availableCount = pieceList.filter((p) => p.status === 'available').length
  const reservedCount = pieceList.filter((p) => p.status === 'reserved').length
  const soldCount = pieceList.filter((p) => p.status === 'sold').length

  const dropDate = sheet.drop_date ? new Date(sheet.drop_date) : null
  const isFuture = dropDate && dropDate > new Date()
  const dropLabel = dropDate
    ? (isFuture
        ? `Dropping ${dropDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}`
        : `Released ${dropDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}`)
    : null

  return (
    <>
      {/* Back nav */}
      <div className="max-w-5xl mx-auto px-4 sm:px-6 pt-4">
        <a
          href={`/p/${studioSlug}`}
          className="text-[12px] text-[var(--color-stone)] hover:text-[var(--color-onyx)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
        >
          ← {studio.name}
        </a>
      </div>

      {/* Sheet hero */}
      <section aria-label="Drop cover">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-8 sm:pb-10">
          {/* Cover image */}
          {sheet.cover_image_url && (
            <div className="relative w-full aspect-[4/3] sm:aspect-[16/9] lg:aspect-[21/9] rounded-lg overflow-hidden border border-[var(--color-border)] mb-6 sm:mb-8 shadow-[var(--shadow-card)]">
              <img
                src={sheet.cover_image_url}
                alt={`${sheet.title} drop cover`}
                className="w-full h-full object-cover"
                loading="eager"
                // @ts-expect-error -- fetchpriority is valid HTML
                fetchpriority="high"
              />
            </div>
          )}

          {/* Drop label */}
          {dropLabel && (
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-2">
              {dropLabel}
            </p>
          )}

          {/* Sheet title */}
          <h1 className="font-serif text-[1.75rem] sm:text-[2.25rem] leading-[2rem] sm:leading-[2.5rem] font-normal text-[var(--color-onyx)]">
            {sheet.title}
          </h1>

          {sheet.description && (
            <p className="text-[14px] text-[var(--color-stone)] mt-3 max-w-2xl leading-relaxed">
              {sheet.description}
            </p>
          )}

          {/* Inventory pulse */}
          <p className="text-[12px] text-[var(--color-stone)] mt-2 tabular-nums">
            {pieceList.length} design{pieceList.length !== 1 ? 's' : ''}
            {availableCount > 0 && <span> · {availableCount} available</span>}
            {reservedCount > 0 && <span> · {reservedCount} reserved</span>}
            {soldCount > 0 && <span> · {soldCount} sold</span>}
          </p>
        </div>
      </section>

      {/* Pieces grid */}
      <section aria-label="Pieces in this drop" className="border-t border-[var(--color-border)]">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-12 sm:pb-16">
          {pieceList.length === 0 ? (
            <div className="text-center py-16">
              <p className="font-serif italic text-[1.25rem] text-[var(--color-onyx)]">
                Nothing here yet.
              </p>
              <p className="text-[13px] text-[var(--color-stone)] mt-2">
                This drop is being prepared. Check back closer to the release date.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-2 sm:gap-3 sm:grid-cols-3 lg:grid-cols-4">
              {pieceList.map((piece, i) => {
                const artist = Array.isArray(piece.artist) ? piece.artist[0] : piece.artist
                return (
                  <FeaturedCard
                    key={piece.id}
                    variant="flash"
                    id={piece.id}
                    title={piece.title}
                    watermarked_path={piece.watermarked_path}
                    price_cents={piece.price_cents}
                    currency={piece.currency}
                    status={piece.status}
                    is_one_of_one={piece.is_one_of_one}
                    artist={artist as { display_name: string; slug: string | null } | null}
                    studioSlug={studioSlug}
                    priority={i === 0}
                  />
                )
              })}
            </div>
          )}
        </div>
      </section>
    </>
  )
}

