// ── createFlashSheet ──────────────────────────────────────────────────────────

export async function createFlashSheet(
  input: z.infer<typeof CreateFlashSheetSchema>,
): Promise<{ success: true; sheetId: string } | { success: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const parsed = CreateFlashSheetSchema.safeParse(input)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Invalid input' }
  }

  const d = parsed.data
  const slug = generateSlug(d.title)
  const supabase = await createClient()

  const { data, error } = await (supabase.from('flash_sheets' as never) as ReturnType<typeof supabase.from>)
    .insert({
      studio_id: auth.studioId,
      title: d.title,
      slug,
      description: d.description ?? null,
      drop_date: d.dropDate ?? null,
      cover_image_url: d.coverImageUrl ?? null,
      status: 'draft',
      created_by: auth.user.authId,
    } as never)
    .select('id' as never)
    .single()

  if (error) {
    const err = error as { code: string; message: string }
    if (err.code === '23505') {
      return { success: false, error: 'A sheet with this title already exists' }
    }
    return { success: false, error: err.message }
  }

  const row = data as { id: string }
  return { success: true, sheetId: row.id }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function generateSlug(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 60)
}

function generateUploadId(): string {
  const ts = Date.now().toString(36).padStart(9, '0')
  const rand = Math.random().toString(36).slice(2, 11)
  return `${ts}${rand}`
}

