/**
 * POST /api/flash/[id]/reserve
 * Public route. Rate-limited. Anonymous Supabase client.
 * S13: flash_pieces table uses `as never` cast until pnpm db:types.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { getDodoClient } from '@/lib/dodo/client'
import { publicBookingCreateRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

const ReserveBodySchema = z.object({
  clientEmail: z.string().email(),
  clientName: z.string().min(1).max(120),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

interface PieceRow {
  id: string
  studio_id: string
  deposit_cents: number
  price_cents: number
  currency: string
  status: string
  visibility: string
  title: string
  studio: Array<{ id: string; name: string; slug: string }> | { id: string; name: string; slug: string } | null
}

export async function POST(req: NextRequest, ctx: RouteContext): Promise<NextResponse> {
  const { id: pieceId } = await ctx.params

  const ip = getClientIp(req)
  const rl = await publicBookingCreateRatelimit.limit(`flash-reserve:${ip}`)
  if (!rl.success) {
    return NextResponse.json(
      { error: 'Too many requests. Please wait before trying again.' },
      { status: 429 },
    )
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ReserveBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.errors[0]?.message ?? 'Invalid input' },
      { status: 400 },
    )
  }

  const { clientEmail, clientName } = parsed.data

  const supabase = await createClient()

  // S13: flash_pieces not in types yet
  const { data: pieceRaw, error: pieceErr } = await (supabase
    .from('flash_pieces' as never) as ReturnType<typeof supabase.from>)
    .select('id, studio_id, deposit_cents, price_cents, currency, status, visibility, title, studio:studios(id, name, slug)' as never)
    .eq('id' as never, pieceId)
    .eq('visibility' as never, 'public')
    .eq('status' as never, 'available')
    .maybeSingle()

  if (pieceErr || !pieceRaw) {
    return NextResponse.json({ error: 'Flash piece not available for reservation' }, { status: 404 })
  }

  const piece = pieceRaw as unknown as PieceRow

  if (piece.status !== 'available') {
    return NextResponse.json({ error: 'This piece is no longer available' }, { status: 409 })
  }

  const studio = Array.isArray(piece.studio) ? piece.studio[0] : piece.studio
  const studioSlug = studio?.slug ?? ''
  const siteUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://inkos.studio'

  try {
    const dodo = getDodoClient()

    const session = await (dodo as unknown as {
      payments: {
        create: (body: Record<string, unknown>) => Promise<{ payment_link: string }>
      }
    }).payments.create({
      billing: {
        city: 'N/A',
        country: 'US',
        state: 'N/A',
        street: 'N/A',
        zipcode: '00000',
      },
      customer: {
        email: clientEmail,
        name: clientName,
      },
      product_cart: [
        {
          product_id: process.env.DODO_PRODUCT_FLASH_DEPOSIT ?? 'flash_deposit',
          quantity: 1,
          unit_amount: piece.deposit_cents > 0 ? piece.deposit_cents : piece.price_cents,
          name: `Reserve: ${piece.title}`,
        },
      ],
      return_url: `${siteUrl}/p/${studioSlug}/flash/${pieceId}?reserved=1`,
      metadata: {
        kind: 'flash_reserve',
        studioId: piece.studio_id,
        flash_piece_id: pieceId,
        client_email: clientEmail,
        client_name: clientName,
      },
    })

    return NextResponse.json({ checkoutUrl: session.payment_link, pieceId })
  } catch (err) {
    logger.error({ err, pieceId }, 'flash reserve: Dodo checkout creation failed')
    return NextResponse.json({ error: 'Payment setup failed. Please try again.' }, { status: 500 })
  }
}

